import { useCallback, useEffect, useRef, useState } from 'react';
import { Game } from './game/engine';
import { Input } from './game/input';
import { audio } from './game/audio';
import type { DialogState, DiffKey, EndStats, HudState } from './game/types';
import { Menu } from './components/Menu';
import { Hud } from './components/Hud';
import { DialogBox, GameOver, PauseMenu } from './components/Overlays';
import { TouchControls } from './components/TouchControls';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const STYLE = `
.rp-root { font-family: ui-monospace, 'Cascadia Mono', 'Courier New', monospace; }
.rp-panel { background: #1b1430e6; border: 3px solid #f4e3b5; box-shadow: 0 0 0 3px #1b1226, 6px 6px 0 3px rgba(0,0,0,.45); image-rendering: pixelated; }
.rp-btn { border: 3px solid #1b1226; box-shadow: inset -3px -3px 0 rgba(0,0,0,.3), inset 3px 3px 0 rgba(255,255,255,.35); transition: transform .08s; }
.rp-btn:active { transform: translateY(2px); }
.rp-title { color: #ffd447; text-shadow: 3px 0 0 #1b1226, -3px 0 0 #1b1226, 0 3px 0 #1b1226, 0 -3px 0 #1b1226, 6px 6px 0 #e63946, 9px 9px 0 #1b1226; letter-spacing: .06em; }
@keyframes rp-float { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-6px) } }
.rp-float { animation: rp-float 2.4s ease-in-out infinite; }
@keyframes rp-blink { 50% { opacity: .2 } }
.rp-blink { animation: rp-blink 1s steps(1) infinite; }
@keyframes rp-pop { 0% { transform: translateY(10px) scale(.7) } 50% { transform: scale(1.06) } 100% { transform: scale(1) } }
.rp-pop { animation: rp-pop .6s ease-out both; }
`;

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [input, setInput] = useState<Input | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudState | null>(null);
  const [dialog, setDialog] = useState<DialogState | null>(null);
  const [end, setEnd] = useState<EndStats | null>(null);
  const [diff, setDiff] = useState<DiffKey>('normal');
  const [muted, setMuted] = useState(false);
  const [hi, setHi] = useState(0);

  useEffect(() => {
    const inp = new Input();
    inp.attach();
    setInput(inp);
    const g = new Game(canvasRef.current!, inp, {
      onHud: setHud,
      onDialog: setDialog,
      onEnd: s => { setEnd(s); setHi(s.hi); setScreen('over'); },
    });
    gameRef.current = g;
    setHi(g.hi);
    const wrap = wrapRef.current!;
    const fit = () => { const r = wrap.getBoundingClientRect(); g.resize(r.width, r.height); };
    const ro = new ResizeObserver(fit);
    ro.observe(wrap);
    fit();
    g.run();
    return () => { ro.disconnect(); g.destroy(); inp.detach(); audio.dispose(); gameRef.current = null; };
  }, []);

  const play = useCallback(() => {
    (document.activeElement as HTMLElement | null)?.blur?.();
    audio.init();
    gameRef.current?.start(diff);
    setEnd(null);
    setScreen('play');
  }, [diff]);

  const setPaused = useCallback((v: boolean) => {
    if (gameRef.current) gameRef.current.paused = v;
    setScreen(v ? 'pause' : 'play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract();
    setHi(gameRef.current?.hi ?? 0);
    setHud(null); setDialog(null);
    setScreen('menu');
  }, []);

  const toggleMute = useCallback(() => { setMuted(m => { audio.setMuted(!m); return !m; }); }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      if (screen === 'play') setPaused(true);
      else if (screen === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [screen, setPaused]);

  return (
    <div ref={wrapRef} className="rp-root relative h-full min-h-[100vh] w-full select-none overflow-hidden bg-[#0b0912]" style={{ touchAction: 'none' }}>
      <style>{STYLE}</style>
      <canvas
        ref={canvasRef}
        className="absolute inset-0 h-full w-full"
        style={{ imageRendering: 'pixelated' }}
        onPointerDown={() => { if (screen === 'play' && !dialog) input?.press('atk'); }}
      />
      {screen === 'menu' && <Menu diff={diff} setDiff={setDiff} hi={hi} muted={muted} onMute={toggleMute} onPlay={play} />}
      {screen !== 'menu' && hud && <Hud hud={hud} muted={muted} onMute={toggleMute} onPause={() => setPaused(true)} />}
      {screen === 'play' && dialog && <DialogBox d={dialog} onNext={() => gameRef.current?.advance()} onChoose={id => gameRef.current?.choose(id)} />}
      {screen === 'play' && !dialog && <TouchControls input={input} />}
      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && end && <GameOver s={end} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useMemo } from 'react';
import { Pause, ScrollText, Volume2, VolumeX } from 'lucide-react';
import type { HudState } from '../game/types';
import { item, sword, spriteURL } from '../game/sprites';

interface Props { hud: HudState; muted: boolean; onMute: () => void; onPause: () => void }
const PX = { imageRendering: 'pixelated' as const };

function Slot({ img, label, n, dim, k }: { img: string; label: string; n?: string; dim?: boolean; k?: string }) {
  return (
    <div title={label} className={`relative flex h-12 w-12 items-center justify-center border-2 border-[#f4e3b5]/70 bg-[#1b1430]/85 shadow-[0_0_0_2px_#1b1226] ${dim ? 'opacity-35' : ''}`}>
      <img src={img} alt={label} className="h-8 w-8" style={PX} />
      {n && <span className="absolute -bottom-1 -right-1 bg-[#1b1226] px-1 text-[11px] font-black text-[#ffd447]">{n}</span>}
      {k && <span className="absolute -left-1 -top-1 bg-[#e63946] px-1 text-[9px] font-black text-white">{k}</span>}
    </div>
  );
}

export function Hud({ hud, muted, onMute, onPause }: Props) {
  const img = useMemo(() => ({
    heart: spriteURL(item('corazon', 0), 3), coin: spriteURL(item('moneda', 0), 3), potion: spriteURL(item('pocion', 0), 3), key: spriteURL(item('llave', 0), 3),
    wing: spriteURL(item('ala', 0), 3), boots: spriteURL(item('botas', 0), 3), fury: spriteURL(item('furia', 0), 3),
    s1: spriteURL(sword(1), 3), s2: spriteURL(sword(2), 3), s3: spriteURL(sword(3), 3),
  }), []);
  const hearts = Math.ceil(hud.maxHp / 2);
  return (
    <div className="pointer-events-none absolute inset-0 text-[#f4e3b5]">
      <div className="absolute left-3 top-3 flex flex-col gap-2">
        <div className="flex max-w-[16rem] flex-wrap gap-0.5">
          {Array.from({ length: hearts }, (_, i) => {
            const v = Math.max(0, Math.min(2, hud.hp - i * 2));
            return (
              <div key={i} className="relative h-7 w-7">
                <img src={img.heart} alt="" className="absolute inset-0 h-7 w-7 opacity-30 grayscale" style={PX} />
                <div className="absolute inset-0 overflow-hidden" style={{ width: `${v * 50}%` }}><img src={img.heart} alt="" className="h-7 w-7 max-w-none" style={PX} /></div>
              </div>
            );
          })}
        </div>
        <div className="flex items-center gap-3 bg-[#1b1430]/80 px-2 py-1 shadow-[0_0_0_2px_#1b1226]">
          <span className="flex items-center gap-1 font-black text-[#ffd447]"><img src={img.coin} alt="" className="h-5 w-5" style={PX} />{hud.coins}</span>
          <span className="text-xs font-black">NV {hud.lvl}</span>
          <div className="h-2 w-20 bg-black/60"><div className="h-full bg-[#7fd3c6]" style={{ width: `${(hud.xp / hud.xpNext) * 100}%` }} /></div>
        </div>
      </div>

      <div className="absolute left-1/2 top-3 w-[min(92vw,30rem)] -translate-x-1/2 text-center">
        <div className="mx-auto inline-flex max-w-full items-center gap-2 bg-[#1b1430]/85 px-3 py-1.5 shadow-[0_0_0_2px_#1b1226]">
          <ScrollText size={16} className="shrink-0 text-[#ffd447]" />
          <span className="truncate text-sm font-bold">{hud.quest}</span>
        </div>
        <div className="mt-1 text-[10px] font-bold tracking-[0.3em] text-[#7fd3c6] [text-shadow:1px_1px_0_#000,-1px_-1px_0_#000,1px_-1px_0_#000,-1px_1px_0_#000]">{hud.area.toUpperCase()}</div>
        {hud.boss !== null && (
          <div className="mx-auto mt-2 w-full max-w-sm">
            <div className="mb-0.5 text-xs font-black tracking-widest text-[#ff9a9a]">REY GÓLEM</div>
            <div className="h-3 border-2 border-[#1b1226] bg-black/70"><div className="h-full bg-gradient-to-r from-[#e63946] to-[#ff7a2a] transition-all" style={{ width: `${hud.boss * 100}%` }} /></div>
          </div>
        )}
      </div>

      <div className="pointer-events-auto absolute right-3 top-3 flex items-start gap-2">
        <div className="bg-[#1b1430]/85 px-3 py-1 text-right shadow-[0_0_0_2px_#1b1226]">
          <div className="text-[9px] font-bold tracking-widest text-[#7fd3c6]">PUNTOS</div>
          <div className="text-lg font-black leading-none text-[#ffd447]">{hud.score.toLocaleString('es-ES')}</div>
        </div>
        <button onClick={onMute} aria-label="Silenciar" className="rp-btn bg-[#2a2140] p-2 text-[#ffd447]">{muted ? <VolumeX size={16} /> : <Volume2 size={16} />}</button>
        <button onClick={onPause} aria-label="Pausa" className="rp-btn bg-[#2a2140] p-2 text-[#ffd447]"><Pause size={16} /></button>
      </div>

      <div className="absolute bottom-3 left-1/2 flex -translate-x-1/2 gap-2">
        <Slot img={hud.sword >= 3 ? img.s3 : hud.sword === 2 ? img.s2 : img.s1} label="Espada" n={`Nv${hud.sword}`} />
        <Slot img={img.potion} label="Pociones" n={`x${hud.potions}`} dim={!hud.potions} k="Q" />
        <Slot img={img.key} label="Llaves" n={`x${hud.keys}`} dim={!hud.keys} />
        <Slot img={img.wing} label="Alas" n={`${hud.wings}/3`} dim={!hud.wings} />
        <Slot img={img.boots} label="Botas veloces" dim={!hud.boots} />
        {hud.fury > 0 && <Slot img={img.fury} label="Furia" n={`${Math.ceil(hud.fury)}s`} />}
      </div>

      {hud.bannerT > 0 && hud.banner && (
        <div className="absolute inset-x-0 top-[17%] flex justify-center px-4" style={{ opacity: Math.min(1, hud.bannerT * 1.5) }}>
          <div key={hud.banner} className="rp-pop bg-[#1b1430]/85 px-6 py-3 text-center text-xl font-black tracking-wide text-[#ffd447] shadow-[0_0_0_3px_#1b1226,0_0_0_6px_#f4e3b5]">{hud.banner}</div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useMemo } from 'react';
import type { ReactNode } from 'react';
import { ChevronRight, Coins, Crown, Home, Play, RotateCcw, Skull, Trophy } from 'lucide-react';
import confetti from 'canvas-confetti';
import type { DialogState, EndStats } from '../game/types';
import { npc, spriteURL } from '../game/sprites';

const Btn = ({ onClick, children, main }: { onClick: () => void; children: ReactNode; main?: boolean }) => (
  <button onClick={onClick} className={`rp-btn flex w-full items-center justify-center gap-2 px-5 py-3 text-lg font-black ${main ? 'bg-[#e63946] text-white hover:bg-[#ff4d5a]' : 'bg-[#2a2140] text-[#f4e3b5] hover:bg-[#3a2f58]'}`}>{children}</button>
);

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-[#0b0912]/70 p-4">
      <div className="rp-panel w-full max-w-xs p-6 text-center text-[#f4e3b5]">
        <h2 className="rp-title mb-6 text-4xl font-black">PAUSA</h2>
        <div className="flex flex-col gap-3">
          <Btn onClick={onResume} main><Play size={18} /> Continuar</Btn>
          <Btn onClick={onRestart}><RotateCcw size={18} /> Reiniciar</Btn>
          <Btn onClick={onMenu}><Home size={18} /> Menú</Btn>
        </div>
        <p className="mt-4 text-xs text-[#a89c80]">P / Esc para continuar</p>
      </div>
    </div>
  );
}

export function GameOver({ s, onRetry, onMenu }: { s: EndStats; onRetry: () => void; onMenu: () => void }) {
  useEffect(() => {
    if (!s.win && !s.record) return;
    const fire = () => confetti({ particleCount: 120, spread: 80, origin: { y: 0.6 }, colors: ['#ffd447', '#e63946', '#7fd3c6', '#f4e3b5'] });
    fire(); const id = window.setTimeout(fire, 700);
    return () => window.clearTimeout(id);
  }, [s]);
  const mm = Math.floor(s.time / 60), ss = Math.floor(s.time % 60).toString().padStart(2, '0');
  const rows: [string, string][] = [['Dificultad', s.diff], ['Nivel alcanzado', String(s.lvl)], ['Enemigos derrotados', String(s.kills)], ['Monedas reunidas', String(s.coins)], ['Tiempo', `${mm}:${ss}`]];
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-[#0b0912]/75 p-4">
      <div className="rp-panel w-full max-w-sm p-6 text-center text-[#f4e3b5]">
        <div className="mb-2 flex justify-center">{s.win ? <Crown size={44} className="text-[#ffd447]" /> : <Skull size={44} className="text-[#ff9a9a]" />}</div>
        <h2 className="rp-title text-3xl font-black sm:text-4xl">{s.win ? '¡VICTORIA!' : 'HAS CAÍDO'}</h2>
        <p className="mt-2 text-sm text-[#c8bca0]">{s.win ? 'El Rey Gólem ha caído y el Reino Pixel vuelve a brillar.' : 'Tu aventura termina aquí... por ahora.'}</p>
        <div className="mt-4 text-5xl font-black text-[#ffd447]">{s.score.toLocaleString('es-ES')}</div>
        {s.record ? <div className="rp-blink mt-1 text-sm font-black text-[#7fd3c6]">¡NUEVO RÉCORD!</div>
          : <div className="mt-1 flex items-center justify-center gap-1 text-xs text-[#a89c80]"><Trophy size={12} /> Récord: {s.hi.toLocaleString('es-ES')}</div>}
        <ul className="my-5 space-y-1 bg-black/30 p-3 text-left text-sm">
          {rows.map(([k, v]) => <li key={k} className="flex justify-between"><span className="text-[#c8bca0]">{k}</span><b>{v}</b></li>)}
        </ul>
        <div className="flex flex-col gap-3">
          <Btn onClick={onRetry} main><RotateCcw size={18} /> Reintentar</Btn>
          <Btn onClick={onMenu}><Home size={18} /> Menú</Btn>
        </div>
      </div>
    </div>
  );
}

interface DialogProps { d: DialogState; onNext: () => void; onChoose: (id: string) => void }

export function DialogBox({ d, onNext, onChoose }: DialogProps) {
  const face = useMemo(() => spriteURL(npc(d.look, 0), 5), [d.look]);
  return (
    <div className="absolute inset-x-0 bottom-20 flex justify-center px-3">
      <div className="rp-panel flex w-full max-w-2xl gap-4 p-4 text-[#f4e3b5]" onClick={() => { if (!d.choices) onNext(); }}>
        <div className="hidden h-24 w-24 shrink-0 items-end justify-center bg-[#2a2140] shadow-[inset_0_0_0_2px_#1b1226] sm:flex">
          <img src={face} alt={d.name} className="h-[100px]" style={{ imageRendering: 'pixelated' }} />
        </div>
        <div className="flex-1">
          <div className="mb-1 text-sm font-black tracking-widest text-[#ffd447]">{d.name}</div>
          <p className="text-base leading-relaxed">{d.text}</p>
          {d.choices ? (
            <div className="mt-3 grid gap-2 sm:grid-cols-2">
              {d.choices.map((c, i) => (
                <button key={c.id} onClick={() => onChoose(c.id)} className="rp-btn flex items-center justify-between gap-2 bg-[#2a2140] px-3 py-2 text-left text-sm font-bold hover:bg-[#3a2f58]">
                  <span><span className="mr-2 text-[#7fd3c6]">{i + 1}</span>{c.label}</span>
                  {c.cost > 0 && <span className="flex items-center gap-1 text-[#ffd447]"><Coins size={14} />{c.cost}</span>}
                </button>
              ))}
            </div>
          ) : (
            <div className="rp-blink mt-2 flex items-center justify-end gap-1 text-xs font-bold text-[#7fd3c6]">E / Espacio <ChevronRight size={14} /></div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useRef, useState } from 'react';
import type { PointerEvent } from 'react';
import { FlaskConical, Footprints, Hand, Sword } from 'lucide-react';
import type { Input } from '../game/input';

const R = 46;

export function TouchControls({ input }: { input: Input | null }) {
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));
  const [knob, setKnob] = useState({ x: 0, y: 0 });
  const base = useRef<HTMLDivElement>(null);
  const pid = useRef<number | null>(null);
  if (!touch || !input) return null;

  const move = (e: PointerEvent) => {
    if (pid.current !== e.pointerId || !base.current) return;
    const r = base.current.getBoundingClientRect();
    let x = e.clientX - (r.left + r.width / 2), y = e.clientY - (r.top + r.height / 2);
    const m = Math.hypot(x, y); if (m > R) { x = (x / m) * R; y = (y / m) * R; }
    setKnob({ x, y }); input.joy.x = x / R; input.joy.y = y / R;
  };
  const end = (e: PointerEvent) => { if (pid.current !== e.pointerId) return; pid.current = null; setKnob({ x: 0, y: 0 }); input.joy.x = 0; input.joy.y = 0; };
  const btn = (a: string, Icon: typeof Sword, cls: string, label: string) => (
    <button aria-label={label} onPointerDown={e => { e.preventDefault(); input.press(a); }}
      className={`rp-btn flex items-center justify-center rounded-full text-white ${cls}`}><Icon size={a === 'atk' ? 30 : 20} /></button>
  );

  return (
    <>
      <div ref={base} className="absolute bottom-20 left-6 h-32 w-32 rounded-full border-4 border-[#f4e3b5]/40 bg-black/30"
        onPointerDown={e => { pid.current = e.pointerId; (e.target as HTMLElement).setPointerCapture(e.pointerId); move(e); }}
        onPointerMove={move} onPointerUp={end} onPointerCancel={end}>
        <div className="pointer-events-none absolute left-1/2 top-1/2 h-14 w-14 rounded-full border-4 border-[#1b1226] bg-[#ffd447]/80"
          style={{ transform: `translate(calc(-50% + ${knob.x}px), calc(-50% + ${knob.y}px))` }} />
      </div>
      <div className="absolute bottom-20 right-5 grid grid-cols-2 gap-3">
        {btn('use', Hand, 'h-14 w-14 bg-[#2a9d8f]', 'Hablar')}
        {btn('potion', FlaskConical, 'h-14 w-14 bg-[#c2185b]', 'Poción')}
        {btn('dash', Footprints, 'h-16 w-16 bg-[#3a7ad8]', 'Esquivar')}
        {btn('atk', Sword, 'h-20 w-20 bg-[#e63946]', 'Espada')}
      </div>
    </>
  );
}

// Sonido chiptune con Web Audio: efectos y una melodía por zona.
const mtof = (m: number) => 440 * Math.pow(2, (m - 69) / 12);
type Track = { lead: number[]; bass: number[]; bpm: number; wave: OscillatorType };
const TRACKS: Record<string, Track> = {
  pueblo: { bpm: 112, wave: 'square', lead: [72, 0, 76, 79, 77, 76, 74, 0, 72, 74, 76, 0, 74, 0, 67, 0, 69, 0, 72, 76, 74, 72, 71, 0, 72, 0, 79, 0, 76, 0, 0, 0], bass: [48, 48, 53, 53, 55, 55, 48, 48] },
  bosque: { bpm: 96, wave: 'triangle', lead: [69, 0, 72, 0, 76, 0, 74, 72, 71, 0, 67, 0, 69, 0, 0, 0, 64, 0, 67, 69, 72, 0, 71, 69, 67, 0, 64, 0, 69, 0, 0, 0], bass: [45, 45, 41, 41, 43, 43, 40, 40] },
  mazmorra: { bpm: 84, wave: 'triangle', lead: [57, 0, 60, 0, 63, 0, 62, 0, 57, 0, 56, 0, 55, 0, 0, 0, 57, 0, 60, 63, 66, 0, 63, 0, 62, 0, 60, 0, 57, 0, 0, 0], bass: [33, 33, 32, 32, 31, 31, 32, 32] },
  jefe: { bpm: 150, wave: 'square', lead: [69, 69, 72, 69, 75, 69, 74, 72, 69, 69, 72, 69, 67, 68, 69, 0, 69, 69, 72, 69, 76, 75, 74, 72, 70, 0, 69, 0, 68, 0, 69, 0], bass: [33, 33, 33, 36, 34, 34, 34, 32] },
};

class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private music: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private timer = 0; private step = 0; private nextT = 0; private track: Track | null = null;
  muted = false;

  init() {
    if (this.ctx) { void this.ctx.resume(); return; }
    const w = window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext };
    const AC = w.AudioContext || w.webkitAudioContext; if (!AC) return;
    try { this.ctx = new AC(); } catch { return; }
    const c = this.ctx;
    this.master = c.createGain(); this.music = c.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5; this.music.gain.value = 0.22;
    this.master.connect(c.destination); this.music.connect(this.master);
    const b = c.createBuffer(1, c.sampleRate, c.sampleRate), d = b.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    this.noiseBuf = b;
    this.timer = window.setInterval(() => this.tick(), 60);
  }
  setMuted(m: boolean) { this.muted = m; if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.02); }

  private tone(f: number, dur: number, type: OscillatorType, vol: number, f2?: number, at = 0, dest?: AudioNode) {
    const c = this.ctx; if (!c || !this.master) return;
    const t = at || c.currentTime, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(f, t); if (f2) o.frequency.exponentialRampToValueAtTime(Math.max(20, f2), t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    o.connect(g).connect(dest ?? this.master); o.start(t); o.stop(t + dur + 0.02);
  }
  private noise(dur: number, vol: number, freq: number, f2?: number) {
    const c = this.ctx; if (!c || !this.master || !this.noiseBuf) return;
    const t = c.currentTime, s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
    s.buffer = this.noiseBuf; f.type = 'lowpass'; f.frequency.setValueAtTime(freq, t); if (f2) f.frequency.exponentialRampToValueAtTime(f2, t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f).connect(g).connect(this.master); s.start(t); s.stop(t + dur);
  }

  play(name: string) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    switch (name) {
      case 'swing': this.noise(0.12, 0.25, 4000, 600); break;
      case 'hit': this.tone(320, 0.1, 'square', 0.18, 120); this.noise(0.08, 0.2, 2000); break;
      case 'kill': this.tone(500, 0.18, 'square', 0.16, 80); this.noise(0.25, 0.25, 1500, 200); break;
      case 'hurt': this.tone(220, 0.25, 'sawtooth', 0.2, 70); break;
      case 'coin': this.tone(988, 0.07, 'square', 0.12); this.tone(1319, 0.18, 'square', 0.12, undefined, t + 0.07); break;
      case 'item': [72, 76, 79, 84].forEach((m, i) => this.tone(mtof(m), 0.14, 'square', 0.13, undefined, t + i * 0.08)); break;
      case 'heal': [67, 71, 74, 79].forEach((m, i) => this.tone(mtof(m), 0.12, 'triangle', 0.2, undefined, t + i * 0.06)); break;
      case 'talk': this.tone(660 + Math.random() * 200, 0.04, 'square', 0.06); break;
      case 'dash': this.noise(0.18, 0.18, 800, 3000); break;
      case 'cut': this.noise(0.15, 0.22, 3000, 400); break;
      case 'door': this.tone(110, 0.3, 'sawtooth', 0.15, 60); this.noise(0.3, 0.2, 600); break;
      case 'throw': this.tone(700, 0.08, 'triangle', 0.08, 400); break;
      case 'slam': this.tone(90, 0.5, 'sawtooth', 0.3, 30); this.noise(0.5, 0.4, 900, 80); break;
      case 'summon': this.tone(200, 0.4, 'triangle', 0.2, 800); break;
      case 'level': [60, 64, 67, 72, 76, 79].forEach((m, i) => this.tone(mtof(m), 0.16, 'square', 0.12, undefined, t + i * 0.07)); break;
      case 'win': [72, 72, 72, 76, 79, 84].forEach((m, i) => this.tone(mtof(m), 0.3, 'square', 0.14, undefined, t + i * 0.15)); break;
      case 'over': [67, 63, 60, 55].forEach((m, i) => this.tone(mtof(m), 0.35, 'triangle', 0.2, undefined, t + i * 0.25)); break;
    }
  }

  setTrack(name: string) { const tr = TRACKS[name] || null; if (tr === this.track) return; this.track = tr; this.step = 0; if (this.ctx) this.nextT = this.ctx.currentTime + 0.1; }
  private tick() {
    const c = this.ctx; if (!c || !this.track || !this.music) return;
    const tr = this.track, dur = 60 / tr.bpm / 2;
    if (this.nextT < c.currentTime) this.nextT = c.currentTime + 0.05;
    while (this.nextT < c.currentTime + 0.25) {
      const m = tr.lead[this.step % tr.lead.length]; if (m) this.tone(mtof(m), dur * 0.9, tr.wave, 0.09, undefined, this.nextT, this.music);
      if (this.step % 4 === 0) this.tone(mtof(tr.bass[(this.step / 4) % tr.bass.length]), dur * 3.5, 'triangle', 0.16, undefined, this.nextT, this.music);
      this.nextT += dur; this.step++;
    }
  }
  dispose() { clearInterval(this.timer); this.timer = 0; if (this.ctx) void this.ctx.close(); this.ctx = null; this.track = null; }
}

export const audio = new Sfx();

// Motor principal: bucle, jugador, combate, botín, portales entre zonas y estados de partida.
import { bakeArea, buildAreas, drawTile, isSolid, T, TS } from './maps';
import type { AreaDef, Portal } from './maps';
import { EDEF, makeEnemy, updateEnemy } from './entities';
import type { AiCtx } from './entities';
import { audio } from './audio';
import type { Input } from './input';
import { drawGame } from './render';
import { chestLoot, questText, talk, buy } from './quests';
import { DIFFS, DIR_V } from './types';
import type { AreaId, DialogState, Dir, DiffKey, Enemy, EndStats, FloatText, HudState, NpcDef, Particle, PickKind, Pickup, Shot } from './types';

export interface AreaRT { def: AreaDef; tiles: Uint8Array; base: HTMLCanvasElement; top: HTMLCanvasElement; enemies: Enemy[]; picks: Pickup[]; shots: Shot[] }
export interface Player {
  x: number; y: number; dir: Dir; walk: number; moving: boolean; hp: number; maxHp: number; inv: number; atk: number; atkCool: number;
  swing: number; dash: number; dashCool: number; dvx: number; dvy: number; kx: number; ky: number; coins: number; potions: number;
  keys: number; wings: number; sword: number; boots: boolean; fury: number; lvl: number; xp: number;
}
export interface GameCb { onHud: (h: HudState) => void; onEnd: (s: EndStats) => void; onDialog: (d: DialogState | null) => void }

const REC = 'reino-pixel-record';
const ORDER: AreaId[] = ['pueblo', 'bosque', 'mazmorra'];

export class Game {
  ctx: CanvasRenderingContext2D; light: HTMLCanvasElement;
  W = 1; H = 1; s = 4; camX = 0; camY = 0; t = 0;
  areas!: Record<AreaId, AreaRT>; cur!: AreaRT; p!: Player;
  parts: Particle[] = []; texts: FloatText[] = [];
  shake = 0; hurtFlash = 0; fade = 0; pending: Portal | null = null; banner = ''; bannerT = 0;
  mode: 'attract' | 'play' | 'over' = 'attract'; paused = false; dialog: DialogState[] = [];
  diff: DiffKey = 'normal'; quest = 0; slimes = 0; kills = 0; score = 0; coinsTotal = 0; time = 0; winT = 0; overT = 0; bossDead = false;
  hi = 0; private raf = 0; private last = 0; private hudT = 0;

  constructor(public canvas: HTMLCanvasElement, public input: Input, private cb: GameCb) {
    this.ctx = canvas.getContext('2d')!;
    this.light = document.createElement('canvas');
    try { this.hi = Number(localStorage.getItem(REC)) || 0; } catch { this.hi = 0; }
    this.toAttract();
  }

  // ---------- ciclo de vida ----------
  resize(w: number, h: number) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.W = this.canvas.width = this.light.width = Math.max(1, Math.round(w * dpr));
    this.H = this.canvas.height = this.light.height = Math.max(1, Math.round(h * dpr));
    this.s = Math.max(2, Math.round(Math.min(this.W / 320, this.H / 200)));
    this.ctx.imageSmoothingEnabled = false;
  }
  run() {
    const f = (now: number) => {
      this.raf = requestAnimationFrame(f);
      const dt = Math.min(0.05, Math.max(0, (now - (this.last || now)) / 1000)); this.last = now;
      if (!this.paused) this.update(dt);
      drawGame(this);
      this.hudT -= dt; if (this.hudT <= 0 && this.mode !== 'attract') { this.hudT = 0.1; this.cb.onHud(this.hud()); }
    };
    this.raf = requestAnimationFrame(f);
  }
  destroy() { cancelAnimationFrame(this.raf); this.parts = []; }

  private newWorld() {
    const defs = buildAreas(), mul = DIFFS[this.diff].ehp;
    const rt = {} as Record<AreaId, AreaRT>;
    for (const id of ORDER) {
      const def = defs[id], tiles = def.tiles, open = id === 'mazmorra' ? T.FLOOR : T.GRASS;
      for (const q of [...def.spawns, ...def.npcs, { x: def.start[0], y: def.start[1] }]) { const i = Math.floor(q.y) * def.w + Math.floor(q.x); if (isSolid(tiles[i])) tiles[i] = open; }
      const { base, top } = bakeArea(def, tiles);
      rt[id] = { def, tiles, base, top, picks: [], shots: [], enemies: def.spawns.map(s => makeEnemy(s.kind, s.x * TS + 8, s.y * TS + 8, mul)) };
    }
    this.areas = rt;
  }
  private newPlayer(): Player {
    const hp = DIFFS[this.diff].hearts * 2;
    return { x: 0, y: 0, dir: 3, walk: 0, moving: false, hp, maxHp: hp, inv: 0, atk: 0, atkCool: 0, swing: 0, dash: 0, dashCool: 0, dvx: 0, dvy: 0, kx: 0, ky: 0, coins: 0, potions: 1, keys: 0, wings: 0, sword: 1, boots: false, fury: 0, lvl: 1, xp: 0 };
  }
  toAttract() {
    this.mode = 'attract'; this.paused = false; this.dialog = []; this.cb.onDialog(null);
    this.newWorld(); this.p = this.newPlayer(); this.enter('pueblo', 23, 17, false);
    audio.setTrack('');
  }
  start(diff: DiffKey) {
    this.diff = diff; this.newWorld(); this.p = this.newPlayer();
    Object.assign(this, { quest: 0, slimes: 0, kills: 0, score: 0, coinsTotal: 0, time: 0, winT: 0, overT: 0, bossDead: false, paused: false, pending: null, fade: 0 });
    this.mode = 'play'; this.dialog = []; this.cb.onDialog(null); this.input.clear();
    this.enter('pueblo', 23, 17, true);
  }
  private enter(id: AreaId, tx: number, ty: number, show: boolean) {
    this.cur = this.areas[id]; this.p.x = tx * TS + 8; this.p.y = ty * TS + 8; this.cur.shots = []; this.parts = [];
    if (show) {
      this.banner = this.cur.def.name; this.bannerT = 3; audio.setTrack(id);
      for (let i = 0; i < 36; i++) { const a = (i / 36) * Math.PI * 2, life = 1.6 + Math.random() * 1.6; this.parts.push({ x: this.p.x + Math.cos(a) * 14, y: this.p.y - 6 + Math.sin(a) * 8, vx: Math.cos(a) * 8, vy: -14 - Math.random() * 16, life, max: life, color: i % 3 ? '#ffd447' : '#9ffcff', size: 1, g: 0, glow: true }); }
    }
    this.camera(1, true);
  }

  // ---------- utilidades ----------
  tile(x: number, y: number) { const a = this.cur.def; return x < 0 || y < 0 || x >= a.w || y >= a.h ? T.DWALL : this.cur.tiles[y * a.w + x]; }
  setTile(x: number, y: number, v: number) {
    const a = this.cur.def; this.cur.tiles[y * a.w + x] = v;
    const c = this.cur.base.getContext('2d')!;
    for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) if (x + i >= 0 && y + j >= 0 && x + i < a.w && y + j < a.h) drawTile(c, a, this.cur.tiles, x + i, y + j);
  }
  private solidBox(x: number, y: number, hw: number, hh: number) {
    for (let ty = Math.floor((y - hh) / TS); ty <= Math.floor((y + hh - 0.01) / TS); ty++)
      for (let tx = Math.floor((x - hw) / TS); tx <= Math.floor((x + hw - 0.01) / TS); tx++) if (isSolid(this.tile(tx, ty))) return true;
    return false;
  }
  move(o: { x: number; y: number }, dx: number, dy: number, hw: number, hh: number, fly = false) {
    const a = this.cur.def;
    if (fly) { o.x = Math.max(8, Math.min(a.w * TS - 8, o.x + dx)); o.y = Math.max(8, Math.min(a.h * TS - 8, o.y + dy)); return; }
    if (!this.solidBox(o.x + dx, o.y, hw, hh)) o.x += dx;
    if (!this.solidBox(o.x, o.y + dy, hw, hh)) o.y += dy;
  }
  burst(x: number, y: number, color: string, n: number, sp = 60, glow = false, g = 0) {
    for (let i = 0; i < n && this.parts.length < 380; i++) {
      const a = Math.random() * Math.PI * 2, v = sp * (0.3 + Math.random() * 0.7), life = 0.35 + Math.random() * 0.45;
      this.parts.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - g * 0.3, life, max: life, color, size: Math.random() < 0.3 ? 2 : 1, g, glow });
    }
  }
  text(x: number, y: number, text: string, color: string) { this.texts.push({ x, y, text, color, t: 0 }); }
  say(msg: string) { this.banner = msg; this.bannerT = 2.6; }
  hud(): HudState {
    const p = this.p, boss = this.cur.def.id === 'mazmorra' ? this.cur.enemies.find(e => e.kind === 'jefe') : undefined;
    return { hp: p.hp, maxHp: p.maxHp, coins: p.coins, score: Math.floor(this.score), area: this.cur.def.name, quest: questText(this), potions: p.potions, keys: p.keys,
      wings: p.wings, sword: p.sword, boots: p.boots, fury: p.fury, lvl: p.lvl, xp: p.xp, xpNext: this.xpNext(), dash: Math.max(0, p.dashCool),
      boss: boss && !boss.dead && (boss.st !== 0 || boss.hp < boss.maxHp) ? boss.hp / boss.maxHp : null, banner: this.banner, bannerT: this.bannerT };
  }
  xpNext() { return 8 + this.p.lvl * 6; }

  // ---------- actualización ----------
  private update(dt: number) {
    this.t += dt; this.shake = Math.max(0, this.shake - dt * 30); this.hurtFlash = Math.max(0, this.hurtFlash - dt); this.bannerT = Math.max(0, this.bannerT - dt);
    if (this.pending) { this.fade += dt * 3.5; if (this.fade >= 1) { const q = this.pending; this.pending = null; this.enter(q.to, q.tx, q.ty, true); } }
    else this.fade = Math.max(0, this.fade - dt * 3);
    this.updateFx(dt);
    if (this.mode === 'attract') { this.updateEnemies(dt, -9999, -9999); this.camera(dt, false); return; }
    if (this.dialog.length) { this.dialogInput(); return; }
    if (this.mode === 'over') { this.overT -= dt; if (this.overT <= 0 && this.overT > -1) { this.overT = -5; this.finish(false); } return; }
    this.time += dt;
    if (!this.pending) this.updatePlayer(dt);
    this.updateEnemies(dt, this.p.x, this.p.y);
    this.updateShots(dt); this.updatePicks(dt);
    if (this.bossDead) { this.winT += dt; if (this.winT > 3.2 && this.mode === 'play') { this.mode = 'over'; this.overT = -5; this.finish(true); } }
    this.camera(dt, true);
  }

  private camera(dt: number, follow: boolean) {
    const a = this.cur.def, vw = this.W / this.s, vh = this.H / this.s, mw = a.w * TS, mh = a.h * TS;
    let tx: number, ty: number;
    if (follow) { tx = this.p.x - vw / 2; ty = this.p.y - vh / 2; }
    else { tx = (Math.sin(this.t * 0.08) * 0.5 + 0.5) * (mw - vw); ty = (Math.cos(this.t * 0.06) * 0.5 + 0.5) * (mh - vh); }
    tx = mw <= vw ? (mw - vw) / 2 : Math.max(0, Math.min(mw - vw, tx)); ty = mh <= vh ? (mh - vh) / 2 : Math.max(0, Math.min(mh - vh, ty));
    const k = Math.min(1, dt * 9); this.camX += (tx - this.camX) * k; this.camY += (ty - this.camY) * k;
  }

  private updatePlayer(dt: number) {
    const p = this.p, inp = this.input, ax = inp.axis();
    p.inv -= dt; p.atk -= dt; p.atkCool -= dt; p.dashCool -= dt; p.fury = Math.max(0, p.fury - dt);
    if (inp.take('potion')) this.usePotion();
    if (inp.take('use')) this.interact();
    if (inp.take('dash') && p.dashCool <= 0) {
      const m = Math.hypot(ax.x, ax.y); const [fx, fy] = DIR_V[p.dir];
      p.dvx = m > 0.1 ? ax.x / m : fx; p.dvy = m > 0.1 ? ax.y / m : fy; p.dash = 0.18; p.dashCool = p.boots ? 0.45 : 0.7; audio.play('dash');
    }
    if ((inp.take('atk') || inp.held('atk')) && p.atkCool <= 0) { p.atk = 0.22; p.atkCool = 0.32; p.swing++; audio.play('swing'); this.cutGrass(); }
    let spd = 74 * (p.boots ? 1.3 : 1) * (p.fury > 0 ? 1.15 : 1); if (p.atk > 0) spd *= 0.45;
    if (p.dash > 0) {
      p.dash -= dt; this.move(p, p.dvx * 250 * dt, p.dvy * 250 * dt, 5, 4);
      if (this.parts.length < 380) this.parts.push({ x: p.x + (Math.random() - 0.5) * 8, y: p.y - 6 + (Math.random() - 0.5) * 10, vx: 0, vy: -10, life: 0.3, max: 0.3, color: p.fury > 0 ? '#ffb347' : '#9ffcff', size: 2, g: 0, glow: true });
    } else this.move(p, ax.x * spd * dt + p.kx * dt, ax.y * spd * dt + p.ky * dt, 5, 4);
    p.kx *= 0.82; p.ky *= 0.82;
    p.moving = Math.hypot(ax.x, ax.y) > 0.15; if (p.moving) p.walk += dt * 9;
    if (p.moving && p.atk <= 0) p.dir = Math.abs(ax.x) > Math.abs(ax.y) ? (ax.x < 0 ? 2 : 3) : ax.y < 0 ? 1 : 0;
    const ptx = Math.floor(p.x / TS), pty = Math.floor(p.y / TS);
    for (const q of this.cur.def.portals) if (ptx >= q.x0 && ptx <= q.x1 && pty >= q.y0 && pty <= q.y1) { this.pending = q; break; }
  }

  private cutGrass() {
    const p = this.p, [fx, fy] = DIR_V[p.dir];
    for (const o of [-6, 0, 6]) {
      const tx = Math.floor((p.x + fx * 14 + (fy ? o : 0)) / TS), ty = Math.floor((p.y - 4 + fy * 14 + (fx ? o : 0)) / TS), t = this.tile(tx, ty);
      if (t === T.BUSH || t === T.TALL) {
        this.setTile(tx, ty, T.GRASS); audio.play('cut');
        const cx = tx * TS + 8, cy = ty * TS + 8; this.burst(cx, cy, '#4fa04a', 12, 70, false, 120); this.burst(cx, cy, '#8bd960', 6, 50);
        const r = Math.random(); if (r < 0.3) this.drop('moneda', cx, cy); else if (r < 0.4) this.drop('corazon', cx, cy);
      }
    }
  }

  private aiCtx: AiCtx = {
    px: 0, py: 0, dt: 0, spd: 1, time: 0,
    move: (e, dx, dy, fly) => this.move(e, dx, dy, e.kind === 'jefe' ? 11 : 5, e.kind === 'jefe' ? 7 : 4, fly),
    shoot: s => { if (this.cur.shots.length < 80) this.cur.shots.push(s); },
    summon: (kind, x, y) => { const e = makeEnemy(kind, x, y, DIFFS[this.diff].ehp); e.hx = -1; e.respawn = -1; this.cur.enemies.push(e); this.burst(x, y, '#c77dff', 14, 60, true); },
    quake: n => { this.shake = Math.max(this.shake, n); },
    sfx: n => audio.play(n),
  };

  private updateEnemies(dt: number, px: number, py: number) {
    const k = this.aiCtx; Object.assign(k, { px, py, dt, spd: DIFFS[this.diff].espd * (1 + this.quest * 0.06), time: this.t });
    const list = this.cur.enemies, p = this.p, play = this.mode === 'play';
    for (let i = list.length - 1; i >= 0; i--) {
      const e = list[i];
      if (e.dead) {
        if (e.respawn < 0 || e.kind === 'jefe') { if (e.hx < 0) list.splice(i, 1); continue; }
        e.respawn -= dt;
        if (e.respawn <= 0 && Math.hypot(px - e.hx, py - e.hy) > 170) Object.assign(e, makeEnemy(e.kind, e.hx, e.hy, DIFFS[this.diff].ehp * (1 + this.quest * 0.25)));
        continue;
      }
      updateEnemy(e, k);
      if (!play) continue;
      const er = EDEF[e.kind].r, d = Math.hypot(p.x - e.x, p.y - 5 - e.y);
      if (p.atk > 0.06 && e.swing !== p.swing) {
        const [fx, fy] = DIR_V[p.dir], hx = p.x + fx * 13, hy = p.y - 5 + fy * 13;
        if (Math.hypot(hx - e.x, hy - (e.y - e.z * 0.5)) < 13 + er) this.hitEnemy(e, fx, fy);
      }
      if (d < er + 6 && e.z < 16 && !e.dead) this.hurt(EDEF[e.kind].dmg, e.x, e.y);
    }
    if (this.cur.def.id === 'mazmorra' && play) { const b = list.find(e => e.kind === 'jefe'); audio.setTrack(b && !b.dead && Math.hypot(px - b.x, py - b.y) < 220 ? 'jefe' : this.bossDead ? 'pueblo' : 'mazmorra'); }
  }

  private hitEnemy(e: Enemy, fx: number, fy: number) {
    const p = this.p, dmg = (p.sword + (p.lvl - 1) * 0.35) * (p.fury > 0 ? 2 : 1);
    e.swing = p.swing; e.hp -= dmg; e.hit = 0.18;
    const kb = e.kind === 'jefe' ? 50 : 190; e.kx = fx * kb; e.ky = fy * kb;
    audio.play('hit'); this.shake = Math.max(this.shake, 3);
    this.burst(e.x, e.y - 4, '#ffffff', 8, 90, true); this.text(e.x, e.y - 14, String(Math.round(dmg * 10) / 10), p.fury > 0 ? '#ffb347' : '#ffffff');
    if (e.hp <= 0) this.kill(e);
  }

  private kill(e: Enemy) {
    const def = EDEF[e.kind], mult = DIFFS[this.diff].mult;
    e.dead = true; e.respawn = e.respawn < 0 ? -1 : 40; this.kills++; this.score += def.score * mult; this.gainXp(def.xp);
    const col = e.kind === 'slime' ? '#5fd068' : e.kind === 'slimeRojo' ? '#ff5a6a' : e.kind === 'murcielago' ? '#9a6ad0' : '#ece6d6';
    this.burst(e.x, e.y - 4, col, e.kind === 'jefe' ? 120 : 22, e.kind === 'jefe' ? 160 : 90, false, 60); this.burst(e.x, e.y - 4, '#fff6b0', 8, 50, true);
    audio.play('kill'); this.text(e.x, e.y - 20, `+${Math.round(def.score * mult)}`, '#ffd447');
    if ((e.kind === 'slime' || e.kind === 'slimeRojo') && this.quest === 1) this.slimes = Math.min(6, this.slimes + 1);
    if (e.kind === 'jefe') { this.bossDead = true; this.shake = 14; this.say('¡Rey Gólem derrotado!'); audio.play('win'); for (let i = 0; i < 12; i++) this.drop('gema', e.x, e.y); return; }
    const r = Math.random(), n = 1 + (Math.random() * (e.kind === 'esqueleto' || e.kind === 'slimeRojo' ? 3 : 2) | 0);
    for (let i = 0; i < n; i++) this.drop(Math.random() < 0.12 ? 'gema' : 'moneda', e.x, e.y);
    if (r < 0.16) this.drop('corazon', e.x, e.y); else if (r < 0.2) this.drop('furia', e.x, e.y); else if (r < 0.23) this.drop('pocion', e.x, e.y);
    const pend = this.cur.picks.filter(q => q.kind === 'ala').length;
    if (e.kind === 'murcielago' && this.quest === 2 && this.p.wings + pend < 3 && Math.random() < 0.65) this.drop('ala', e.x, e.y);
  }

  drop(kind: PickKind, x: number, y: number) { this.cur.picks.push({ kind, x: x + (Math.random() - 0.5) * 14, y: y + (Math.random() - 0.5) * 10, z: 4, vz: 70 + Math.random() * 50, t: 0 }); }

  private gainXp(n: number) {
    const p = this.p; p.xp += n;
    while (p.xp >= this.xpNext()) { p.xp -= this.xpNext(); p.lvl++; p.hp = p.maxHp; this.say(`¡Nivel ${p.lvl}! Salud restaurada`); audio.play('level'); this.burst(p.x, p.y - 8, '#ffd447', 40, 110, true); }
  }

  hurt(dmg: number, sx: number, sy: number) {
    const p = this.p; if (p.inv > 0 || p.dash > 0 || this.mode !== 'play' || this.bossDead) return;
    p.hp -= dmg * DIFFS[this.diff].dmg; p.inv = 1.1; this.shake = 7; this.hurtFlash = 0.35; audio.play('hurt');
    const d = Math.hypot(p.x - sx, p.y - sy) || 1; p.kx = ((p.x - sx) / d) * 260; p.ky = ((p.y - sy) / d) * 260;
    this.burst(p.x, p.y - 8, '#ff4d6d', 14, 80);
    if (p.hp <= 0) { p.hp = 0; this.mode = 'over'; this.overT = 1.3; audio.play('over'); audio.setTrack(''); this.burst(p.x, p.y - 8, '#ffffff', 50, 140, true); }
  }

  private updateShots(dt: number) {
    const sh = this.cur.shots, p = this.p;
    for (let i = sh.length - 1; i >= 0; i--) {
      const s = sh[i]; s.x += s.vx * dt; s.y += s.vy * dt; s.t += dt;
      const hitWall = isSolid(this.tile(Math.floor(s.x / TS), Math.floor(s.y / TS))) && this.tile(Math.floor(s.x / TS), Math.floor(s.y / TS)) !== T.WATER;
      if (Math.hypot(p.x - s.x, p.y - 6 - s.y) < 8) { this.hurt(s.dmg, s.x, s.y); sh.splice(i, 1); continue; }
      if (hitWall || s.t > 4) { this.burst(s.x, s.y, s.kind === 'orbe' ? '#ff4fd8' : '#ece6d6', 6, 40, s.kind === 'orbe'); sh.splice(i, 1); }
    }
  }

  private updatePicks(dt: number) {
    const pk = this.cur.picks, p = this.p, mult = DIFFS[this.diff].mult;
    for (let i = pk.length - 1; i >= 0; i--) {
      const q = pk[i]; q.t += dt; q.vz -= 320 * dt; q.z += q.vz * dt;
      if (q.z < 0) { q.z = 0; q.vz = Math.abs(q.vz) > 30 ? -q.vz * 0.45 : 0; }
      const d = Math.hypot(p.x - q.x, p.y - 4 - q.y);
      if (d < 34 && q.t > 0.4) { q.x += ((p.x - q.x) / d) * 130 * dt; q.y += ((p.y - 4 - q.y) / d) * 130 * dt; }
      if (d < 9 && q.t > 0.3) {
        pk.splice(i, 1);
        if (q.kind === 'moneda' || q.kind === 'gema') { const v = q.kind === 'gema' ? 5 : 1; p.coins += v; this.coinsTotal += v; this.score += v * 5 * mult; this.text(q.x, q.y - 10, `+${v}`, '#ffd447'); audio.play('coin'); }
        else if (q.kind === 'corazon') { p.hp = Math.min(p.maxHp, p.hp + 2); audio.play('heal'); this.text(q.x, q.y - 10, '+♥', '#ff6b8b'); }
        else if (q.kind === 'pocion') { p.potions++; audio.play('item'); this.say('Poción obtenida (Q para beber)'); }
        else if (q.kind === 'ala') { p.wings = Math.min(3, p.wings + 1); audio.play('item'); this.say(`Ala de murciélago ${p.wings}/3`); }
        else if (q.kind === 'furia') { p.fury = 10; audio.play('level'); this.say('¡Furia! Daño doble durante 10 s'); }
        this.burst(q.x, q.y, '#fff6b0', 6, 40, true);
      } else if (q.t > 16) pk.splice(i, 1);
    }
  }

  private updateFx(dt: number) {
    for (let i = this.parts.length - 1; i >= 0; i--) { const q = this.parts[i]; q.life -= dt; if (q.life <= 0) { this.parts.splice(i, 1); continue; } q.vy += q.g * dt; q.x += q.vx * dt; q.y += q.vy * dt; q.vx *= 0.96; q.vy *= 0.96; }
    for (let i = this.texts.length - 1; i >= 0; i--) { const f = this.texts[i]; f.t += dt; f.y -= dt * 20; if (f.t > 0.9) this.texts.splice(i, 1); }
  }

  // ---------- interacción, diálogos y fin ----------
  usePotion() {
    const p = this.p; if (this.mode !== 'play') return;
    if (p.potions <= 0 || p.hp >= p.maxHp) { this.say(p.potions <= 0 ? 'No tienes pociones' : 'Tu salud ya está completa'); return; }
    p.potions--; p.hp = Math.min(p.maxHp, p.hp + 6); audio.play('heal'); this.burst(p.x, p.y - 8, '#7dff9a', 26, 70, true);
  }
  interact() {
    const p = this.p, [fx, fy] = DIR_V[p.dir], ax = p.x + fx * 12, ay = p.y - 4 + fy * 12;
    let best: NpcDef | null = null, bd = 30;
    for (const n of this.cur.def.npcs) { const d = Math.hypot(n.x * TS + 8 - ax, n.y * TS + 8 - ay); if (d < bd) { bd = d; best = n; } }
    if (best) { this.openDialog(talk(this, best)); return; }
    const tx = Math.floor(ax / TS), ty = Math.floor((p.y - 4 + fy * 14) / TS), t = this.tile(tx, ty), key = `${tx},${ty}`;
    if (t === T.CHEST) { this.setTile(tx, ty, T.CHESTO); audio.play('item'); this.burst(tx * TS + 8, ty * TS + 6, '#ffd447', 30, 80, true); this.say(chestLoot(this, this.cur.def.chests[key] || 'pocion')); }
    else if (t === T.GATE) {
      if (p.keys > 0) { p.keys--; for (const g of Object.keys(this.cur.def.gates)) { const [gx, gy] = g.split(',').map(Number); this.setTile(gx, gy, this.cur.def.gates[g]); } audio.play('door'); this.shake = 4; this.say('¡La reja se abre!'); }
      else this.say('Está cerrada. Necesitas una llave');
    }
  }
  openDialog(lines: DialogState[]) { this.dialog = lines; this.input.clear(); audio.play('talk'); this.cb.onDialog(lines[0] || null); }
  advance() { this.dialog.shift(); audio.play('talk'); this.cb.onDialog(this.dialog[0] || null); }
  choose(id: string) { this.openDialog(buy(this, id)); }
  private dialogInput() {
    const d = this.dialog[0], inp = this.input;
    if (d.choices) { for (let i = 0; i < d.choices.length; i++) if (inp.take(String(i + 1))) { this.choose(d.choices[i].id); return; } }
    else if (inp.take('use') || inp.take('atk')) this.advance();
  }
  private finish(win: boolean) {
    const p = this.p; if (win) this.score += p.hp * 50 + p.coins * 2;
    const score = Math.floor(this.score), record = score > this.hi;
    if (record) { this.hi = score; try { localStorage.setItem(REC, String(score)); } catch { /* sin almacenamiento */ } }
    this.cb.onHud(this.hud());
    this.cb.onEnd({ win, score, hi: this.hi, record, kills: this.kills, coins: this.coinsTotal, time: this.time, diff: DIFFS[this.diff].label, lvl: p.lvl });
  }
}

// Enemigos: estadísticas e inteligencia (slimes saltarines, murciélagos, esqueletos y el Rey Gólem).
import type { Dir, Enemy, EnemyKind, Shot } from './types';

export const EDEF: Record<EnemyKind, { hp: number; spd: number; dmg: number; score: number; xp: number; r: number; name: string }> = {
  slime: { hp: 3, spd: 46, dmg: 1, score: 10, xp: 2, r: 6, name: 'Slime' },
  slimeRojo: { hp: 6, spd: 62, dmg: 2, score: 25, xp: 4, r: 6, name: 'Slime rojo' },
  murcielago: { hp: 2, spd: 58, dmg: 1, score: 15, xp: 3, r: 5, name: 'Murciélago' },
  esqueleto: { hp: 7, spd: 32, dmg: 2, score: 35, xp: 6, r: 6, name: 'Esqueleto' },
  jefe: { hp: 70, spd: 38, dmg: 3, score: 1500, xp: 60, r: 13, name: 'Rey Gólem' },
};

export function makeEnemy(kind: EnemyKind, x: number, y: number, hpMul: number): Enemy {
  const hp = Math.ceil(EDEF[kind].hp * hpMul);
  return { kind, x, y, vx: 0, vy: 0, kx: 0, ky: 0, hp, maxHp: hp, t: Math.random() * 2, st: 0, cool: 0.5 + Math.random(), hit: 0, z: 0, dir: 0, hx: x, hy: y, dead: false, respawn: 0, swing: -1 };
}

export interface AiCtx {
  px: number; py: number; dt: number; spd: number; time: number;
  move: (e: Enemy, dx: number, dy: number, fly: boolean) => void;
  shoot: (s: Shot) => void;
  summon: (kind: EnemyKind, x: number, y: number) => void;
  quake: (power: number) => void;
  sfx: (name: string) => void;
}

const faceDir = (dx: number, dy: number): Dir => (Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? 2 : 3) : dy < 0 ? 1 : 0);

export function updateEnemy(e: Enemy, k: AiCtx) {
  const dt = k.dt, dx = k.px - e.x, dy = k.py - e.y, d = Math.hypot(dx, dy) || 1, sp = EDEF[e.kind].spd * k.spd;
  e.t += dt; e.hit = Math.max(0, e.hit - dt); e.cool -= dt;
  if (Math.abs(e.kx) + Math.abs(e.ky) > 1) { k.move(e, e.kx * dt, e.ky * dt, e.kind === 'murcielago'); e.kx *= 0.85; e.ky *= 0.85; }
  else { e.kx = 0; e.ky = 0; }
  if (e.hit > 0.05 && e.kind !== 'jefe') return;

  if (e.kind === 'slime' || e.kind === 'slimeRojo') {
    if (e.st === 1) {
      const p = Math.min(1, (e.t) / 0.45); e.z = Math.sin(p * Math.PI) * 9;
      k.move(e, e.vx * dt, e.vy * dt, false);
      if (p >= 1) { e.st = 0; e.z = 0; e.cool = (e.kind === 'slimeRojo' ? 0.45 : 0.8) + Math.random() * 0.6; }
    } else if (e.cool <= 0) {
      e.st = 1; e.t = 0;
      let a = Math.random() * Math.PI * 2;
      if (d < 130) a = Math.atan2(dy, dx) + (Math.random() - 0.5) * 0.5;
      else if (Math.hypot(e.hx - e.x, e.hy - e.y) > 60) a = Math.atan2(e.hy - e.y, e.hx - e.x);
      const v = sp * 1.6; e.vx = Math.cos(a) * v; e.vy = Math.sin(a) * v;
    }
  } else if (e.kind === 'murcielago') {
    e.z = 10 + Math.sin(e.t * 7) * 3;
    let tx: number, ty: number;
    if (d < 120) { tx = dx / d + (-dy / d) * Math.sin(e.t * 3) * 0.8; ty = dy / d + (dx / d) * Math.sin(e.t * 3) * 0.8; }
    else { tx = e.hx + Math.cos(e.t * 0.9) * 40 - e.x; ty = e.hy + Math.sin(e.t * 1.3) * 30 - e.y; const m = Math.hypot(tx, ty) || 1; tx /= m; ty /= m; }
    e.vx += (tx * sp - e.vx) * Math.min(1, dt * 3); e.vy += (ty * sp - e.vy) * Math.min(1, dt * 3);
    k.move(e, e.vx * dt, e.vy * dt, true);
  } else if (e.kind === 'esqueleto') {
    if (d < 150) {
      const want = d > 50 ? 1 : -0.6;
      e.vx = (dx / d) * sp * want; e.vy = (dy / d) * sp * want; e.dir = faceDir(dx, dy);
      if (e.cool <= 0 && d < 140) { e.cool = 2 + Math.random(); k.shoot({ x: e.x, y: e.y - 6, vx: (dx / d) * 95, vy: (dy / d) * 95, t: 0, dmg: 2, kind: 'hueso' }); k.sfx('throw'); }
    } else { if (e.cool <= -2) { e.cool = 0; const a = Math.random() * 6.28; e.vx = Math.cos(a) * sp * 0.5; e.vy = Math.sin(a) * sp * 0.5; e.dir = faceDir(e.vx, e.vy); } }
    k.move(e, e.vx * dt, e.vy * dt, false);
  } else if (e.kind === 'jefe') bossAi(e, k, dx, dy, d, sp);
}

function bossAi(e: Enemy, k: AiCtx, dx: number, dy: number, d: number, sp: number) {
  const rage = e.hp < e.maxHp * 0.5, dt = k.dt;
  if (d > 220 && e.st === 0) return; // dormido hasta que llegas
  if (e.st === 0) { // persigue
    e.vx = (dx / d) * sp * (rage ? 1.4 : 1); e.vy = (dy / d) * sp * (rage ? 1.4 : 1); k.move(e, e.vx * dt, e.vy * dt, false);
    if (e.cool <= 0) { e.st = Math.random() < 0.5 ? 1 : 3; e.t = 0; if (rage && Math.random() < 0.35) e.st = 2; }
  } else if (e.st === 1) { // salto y pisotón
    const p = Math.min(1, e.t / 0.8); e.z = Math.sin(p * Math.PI) * 26;
    if (p < 1) k.move(e, dx * dt * 1.2, dy * dt * 1.2, false);
    else {
      e.z = 0; k.quake(9); k.sfx('slam'); const n = rage ? 16 : 12, off = k.time;
      for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2 + off; k.shoot({ x: e.x, y: e.y, vx: Math.cos(a) * 85, vy: Math.sin(a) * 85, t: 0, dmg: 2, kind: 'orbe' }); }
      e.st = 0; e.cool = rage ? 1.2 : 2;
    }
  } else if (e.st === 2) { // invoca slimes
    if (e.t > 0.6) { for (let i = 0; i < 3; i++) k.summon(rage ? 'slimeRojo' : 'slime', e.x + Math.cos(i * 2.1) * 30, e.y + Math.sin(i * 2.1) * 30); k.sfx('summon'); e.st = 0; e.cool = 2.2; }
  } else if (e.st === 3) { // carga
    if (e.t < 0.5) { e.vx = (dx / d) * 190; e.vy = (dy / d) * 190; }
    else if (e.t < 1.2) k.move(e, e.vx * dt, e.vy * dt, false);
    else { e.st = 0; e.cool = rage ? 1 : 1.8; }
  }
}

// Teclado (escucha en window) + joystick y botones táctiles.
const BLOCK = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space']);
const ACT: Record<string, string> = {
  Space: 'atk', KeyJ: 'atk', KeyZ: 'atk', KeyE: 'use', Enter: 'use', KeyX: 'use',
  ShiftLeft: 'dash', ShiftRight: 'dash', KeyK: 'dash', KeyQ: 'potion', KeyH: 'potion',
  Digit1: '1', Digit2: '2', Digit3: '3', Digit4: '4',
};

export class Input {
  keys = new Set<string>();
  joy = { x: 0, y: 0 };
  private req = new Set<string>();

  private onDown = (e: KeyboardEvent) => {
    if (BLOCK.has(e.code)) e.preventDefault();
    if (!e.repeat && ACT[e.code]) this.req.add(ACT[e.code]);
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  attach() { window.addEventListener('keydown', this.onDown); window.addEventListener('keyup', this.onUp); window.addEventListener('blur', this.onBlur); }
  detach() { window.removeEventListener('keydown', this.onDown); window.removeEventListener('keyup', this.onUp); window.removeEventListener('blur', this.onBlur); }

  press(a: string) { this.req.add(a); }
  take(a: string) { const r = this.req.has(a); this.req.delete(a); return r; }
  clear() { this.req.clear(); }
  held(a: string) { return Object.keys(ACT).some(k => ACT[k] === a && this.keys.has(k)); }

  axis() {
    const k = this.keys;
    let x = this.joy.x, y = this.joy.y;
    if (k.has('ArrowLeft') || k.has('KeyA')) x -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) x += 1;
    if (k.has('ArrowUp') || k.has('KeyW')) y -= 1;
    if (k.has('ArrowDown') || k.has('KeyS')) y += 1;
    const m = Math.hypot(x, y);
    if (m > 1) { x /= m; y /= m; }
    return { x, y };
  }
}

// Mapas por tiles (pueblo, bosque, mazmorra) con semilla fija + su pixel art pre-renderizado.
import type { AreaId, EnemyKind, NpcDef } from './types';

export const T = {
  GRASS: 0, GRASS2: 1, FLOWER: 2, PATH: 3, WATER: 4, SAND: 5, TREE: 6, BUSH: 7, ROCK: 8, HWALL: 9, ROOF: 10,
  DOOR: 11, FENCE: 12, FLOOR: 13, DWALL: 14, TORCH: 15, BRIDGE: 16, CAVE: 17, GATE: 18, CHEST: 19, CHESTO: 20,
  TALL: 21, MUSH: 22, FOUNT: 23, STAIRS: 24, CARPET: 25, PILLAR: 26, WINDOW: 27,
} as const;

const SOLID = new Set<number>([T.WATER, T.TREE, T.BUSH, T.ROCK, T.HWALL, T.ROOF, T.DOOR, T.FENCE, T.DWALL, T.TORCH,
  T.GATE, T.CHEST, T.CHESTO, T.FOUNT, T.PILLAR, T.WINDOW]);
export const isSolid = (t: number) => SOLID.has(t);

export interface Portal { x0: number; y0: number; x1: number; y1: number; to: AreaId; tx: number; ty: number }
export interface Spawn { kind: EnemyKind; x: number; y: number }
export interface AreaDef {
  id: AreaId; name: string; w: number; h: number; tiles: Uint8Array; portals: Portal[]; spawns: Spawn[];
  npcs: NpcDef[]; chests: Record<string, string>; gates: Record<string, number>; start: [number, number];
}

export function rng(seed: number) {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const hash = (x: number, y: number, s: number) => { const n = Math.sin(x * 127.1 + y * 311.7 + s * 74.7) * 43758.5453; return n - Math.floor(n); };
function noise(x: number, y: number, s: number) {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi, s), b = hash(xi + 1, yi, s), c = hash(xi, yi + 1, s), d = hash(xi + 1, yi + 1, s);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

class Grid {
  t: Uint8Array;
  constructor(public w: number, public h: number, fill: number) { this.t = new Uint8Array(w * h).fill(fill); }
  get(x: number, y: number) { return x < 0 || y < 0 || x >= this.w || y >= this.h ? -1 : this.t[y * this.w + x]; }
  set(x: number, y: number, v: number) { if (x >= 0 && y >= 0 && x < this.w && y < this.h) this.t[y * this.w + x] = v; }
  rect(x0: number, y0: number, x1: number, y1: number, v: number) { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) this.set(x, y, v); }
  disc(cx: number, cy: number, rx: number, ry: number, v: number, only?: (t: number) => boolean) {
    for (let y = Math.floor(cy - ry); y <= cy + ry; y++) for (let x = Math.floor(cx - rx); x <= cx + rx; x++) {
      const dx = (x - cx) / rx, dy = (y - cy) / ry;
      if (dx * dx + dy * dy <= 1 && (!only || only(this.get(x, y)))) this.set(x, y, v);
    }
  }
  line(pts: [number, number][], r: number, v: number) {
    for (let i = 0; i < pts.length - 1; i++) {
      const [ax, ay] = pts[i], [bx, by] = pts[i + 1], n = Math.ceil(Math.hypot(bx - ax, by - ay) * 2);
      for (let k = 0; k <= n; k++) this.disc(ax + (bx - ax) * k / n, ay + (by - ay) * k / n, r, r, v);
    }
  }
}

const open = (t: number) => t === T.GRASS || t === T.GRASS2 || t === T.FLOWER || t === T.TALL || t === T.FLOOR;
function scatter(g: Grid, r: () => number, n: number, kind: EnemyKind, x0: number, y0: number, x1: number, y1: number, out: Spawn[]) {
  for (let i = 0, tries = 0; i < n && tries < 600; tries++) {
    const x = x0 + Math.floor(r() * (x1 - x0)), y = y0 + Math.floor(r() * (y1 - y0));
    if (open(g.get(x, y)) && open(g.get(x + 1, y)) && open(g.get(x, y + 1))) { out.push({ kind, x, y }); i++; }
  }
}
function decorate(g: Grid, r: () => number, bush: number, tall: number, mush: number) {
  for (let y = 0; y < g.h; y++) for (let x = 0; x < g.w; x++) {
    if (g.get(x, y) !== T.GRASS && g.get(x, y) !== T.GRASS2) continue;
    let near = false;
    for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) { const t = g.get(x + i, y + j); if (t === T.PATH || t === T.HWALL || t === T.DOOR || t === T.SAND) near = true; }
    const q = r();
    if (!near && q < bush) g.set(x, y, T.BUSH);
    else if (q < bush + tall) g.set(x, y, T.TALL);
    else if (q < bush + tall + mush) g.set(x, y, T.MUSH);
  }
}

function pueblo(): AreaDef {
  const w = 44, h = 32, g = new Grid(w, h, T.GRASS), r = rng(7);
  for (let i = 0; i < g.t.length; i++) { const q = r(); g.t[i] = q < 0.14 ? T.GRASS2 : q < 0.19 ? T.FLOWER : T.GRASS; }
