}

function canopy(c: C, a: AreaDef, x: number, y: number) {
  const p = PALS[a.id], r = rng(x * 31 + y * 17), cx = x * TS + 8 + (r() * 3 | 0) - 1, cy = y * TS - 2;
  blob(c, cx, cy + 2, 10, 9, p.leafD); blob(c, cx - 1, cy, 9, 8, p.leaf);
  blob(c, cx - 3, cy - 3, 4, 3, p.leafL); R(c, cx + 2, cy - 5, 3, 2, p.leafL); R(c, cx - 6, cy + 2, 2, 2, p.leafL);
  R(c, cx + 4, cy + 3, 2, 2, p.leafD); if (a.id === 'pueblo' && r() < 0.3) { R(c, cx + 3, cy - 1, 2, 2, '#ff5a5a'); R(c, cx - 4, cy + 4, 2, 2, '#ff5a5a'); }
}

export function bakeArea(a: AreaDef, tiles: Uint8Array) {
  const base = document.createElement('canvas'), top = document.createElement('canvas');
  base.width = top.width = a.w * TS; base.height = top.height = a.h * TS;
  const bc = base.getContext('2d')!, tc = top.getContext('2d')!;
  for (let y = 0; y < a.h; y++) for (let x = 0; x < a.w; x++) drawTile(bc, a, tiles, x, y);
  for (let y = 0; y < a.h; y++) for (let x = 0; x < a.w; x++) if (tiles[y * a.w + x] === T.TREE) canopy(tc, a, x, y);
  return { base, top };
}

// Misiones, diálogos de los NPC, tienda y contenido de cofres.
import type { Game } from './engine';
import { T, TS } from './maps';
import { audio } from './audio';
import type { AreaId, Choice, DialogState, NpcDef } from './types';

const D = (n: NpcDef, ...lines: string[]): DialogState[] => lines.map(text => ({ name: n.name, look: n.look, text }));
const ORDER: AreaId[] = ['pueblo', 'bosque', 'mazmorra'];

const bossGateClosed = (g: Game) => g.areas.mazmorra.tiles[14 * g.areas.mazmorra.def.w + 30] === T.GATE;

export function questText(g: Game): string {
  const p = g.p;
  if (g.bossDead) return '¡El reino está a salvo!';
  switch (g.quest) {
    case 0: return 'Habla con el Anciano Brizo en la plaza';
    case 1: return g.slimes >= 6 ? 'Vuelve con el Anciano Brizo' : `Derrota slimes (${g.slimes}/6)`;
    case 2: return p.wings >= 3 ? 'Lleva las alas al Anciano Brizo' : `Consigue alas de murciélago en el bosque (${p.wings}/3)`;
    default:
      if (g.cur.def.id !== 'mazmorra') return 'Abre la cueva al noreste del Bosque Susurro';
      return bossGateClosed(g) && p.keys === 0 ? 'Busca la llave del jefe en la mazmorra' : 'Derrota al Rey Gólem';
  }
}

/** Objetivo actual en píxeles dentro de la zona actual (o el portal que lleva hacia él). */
export function questTarget(g: Game): { x: number; y: number } | null {
  const a = g.cur.def, p = g.p;
  let area: AreaId = 'pueblo', x = 0, y = 0;
  const elder = () => { const n = g.areas.pueblo.def.npcs[0]; area = 'pueblo'; x = n.x * TS + 8; y = n.y * TS + 8; };
  const nearest = (kinds: string[]) => {
    let bd = 1e9; let found = false;
    for (const e of g.cur.enemies) if (!e.dead && kinds.includes(e.kind)) { const d = Math.hypot(e.x - p.x, e.y - p.y); if (d < bd) { bd = d; x = e.x; y = e.y; found = true; } }
    return found;
  };
  if (g.bossDead) return null;
  if (g.quest === 0 || (g.quest === 1 && g.slimes >= 6) || (g.quest === 2 && p.wings >= 3)) elder();
  else if (g.quest === 1) { if (nearest(['slime', 'slimeRojo'])) return { x, y }; area = 'bosque'; x = 20 * TS; y = 20 * TS; }
  else if (g.quest === 2) { if (a.id === 'bosque' && nearest(['murcielago'])) return { x, y }; area = 'bosque'; x = 30 * TS; y = 20 * TS; }
  else {
    area = 'mazmorra';
    if (a.id === 'bosque') { area = 'bosque'; x = 45.5 * TS + 8; y = 5 * TS; }
    else if (a.id === 'mazmorra') {
      if (bossGateClosed(g) && p.keys === 0) { x = 8 * TS + 8; y = 11 * TS + 8; }
      else { const b = g.cur.enemies.find(e => e.kind === 'jefe'); x = b ? b.x : 38 * TS; y = b ? b.y : 9 * TS; }
    }
  }
  if (area === a.id) return { x, y };
  const step = ORDER.indexOf(area) > ORDER.indexOf(a.id) ? 1 : -1, to = ORDER[ORDER.indexOf(a.id) + step];
  const q = a.portals.find(o => o.to === to);
  return q ? { x: ((q.x0 + q.x1) / 2) * TS + 8, y: ((q.y0 + q.y1) / 2) * TS + 8 } : null;
}

function shopChoices(g: Game): Choice[] {
  const c: Choice[] = [{ id: 'pocion', label: 'Poción curativa', cost: 15 }];
  if (g.p.sword === 1) c.push({ id: 'espada', label: 'Espada de acero (+daño)', cost: 40 });
  else if (g.p.sword === 2) c.push({ id: 'espada', label: 'Espada rúnica (+daño)', cost: 90 });
  if (g.p.maxHp < 20) c.push({ id: 'corazon', label: 'Contenedor de corazón', cost: 60 });
  c.push({ id: 'salir', label: 'Nada, gracias', cost: 0 });
  return c;
}

export function talk(g: Game, n: NpcDef): DialogState[] {
  const p = g.p;
  if (n.id === 'anciano') {
    if (g.quest === 0) { g.quest = 1; g.slimes = 0; return D(n, '¡Por fin llega un aventurero! El Reino Pixel está en peligro.', 'Los slimes han invadido los prados. Derrota a 6 y vuelve a verme.', 'Usa ESPACIO para tu espada y SHIFT para esquivar. ¡Suerte!'); }
    if (g.quest === 1 && g.slimes < 6) return D(n, `Aún quedan slimes por ahí... llevas ${g.slimes} de 6.`);
    if (g.quest === 1) { g.quest = 2; p.coins += 25; g.coinsTotal += 25; p.wings = 0; audio.play('item'); return D(n, '¡Magnífico! Toma estas 25 monedas.', 'Algo despertó en la cueva del bosque. Los murciélagos huyen de ella...', 'Tráeme 3 alas de murciélago y forjaré la llave de la cueva.'); }
    if (g.quest === 2 && p.wings < 3) return D(n, `Necesito 3 alas de murciélago (tienes ${p.wings}). Están en el Bosque Susurro, al este.`);
    if (g.quest === 2) { g.quest = 3; p.wings = 0; p.keys++; audio.play('item'); return D(n, 'Con estas alas... ¡listo! La Llave de la Cueva.', 'El Rey Gólem duerme en la mazmorra. Derrótalo y salva el reino.'); }
    return D(n, 'La cueva está al noreste del bosque. ¡Confío en ti, héroe!');
  }
  if (n.id === 'mercader') return [{ name: n.name, look: n.look, text: `¡Bienvenido a mi tienda! Tienes ${p.coins} monedas. ¿Qué te llevas?`, choices: shopChoices(g) }];
  if (n.id === 'nina') return D(n, '¡Hola! Dicen que en el bosque hay un cofre con unas botas mágicas.', 'Corta arbustos y hierba alta con la espada: ¡a veces esconden monedas y corazones!');
  if (n.id === 'guardia') return g.quest < 3 ? D(n, 'Alto. Nadie entra en la cueva sin la llave del Anciano Brizo.') : D(n, 'Esa llave abre la reja. Dentro hace frío... y huele a piedra vieja.');
  return D(n, '...');
}

export function buy(g: Game, id: string): DialogState[] {
  const p = g.p, n = g.areas.pueblo.def.npcs[1], c = shopChoices(g).find(o => o.id === id);
  if (!c || id === 'salir') return D(n, '¡Vuelve cuando quieras, aventurero!');
  if (p.coins < c.cost) return [{ name: n.name, look: n.look, text: `Te faltan ${c.cost - p.coins} monedas. ¡Corta slimes y vuelve!`, choices: shopChoices(g) }];
  p.coins -= c.cost; audio.play('item');
  if (id === 'pocion') p.potions++;
  if (id === 'espada') p.sword++;
  if (id === 'corazon') { p.maxHp += 2; p.hp = p.maxHp; }
  return [{ name: n.name, look: n.look, text: `¡${c.label}! Buena elección. Te quedan ${p.coins} monedas.`, choices: shopChoices(g) }];
}

export function chestLoot(g: Game, what: string): string {
  const p = g.p;
  if (what === 'botas') { p.boots = true; return '¡Botas veloces! Corres y esquivas más rápido'; }
  if (what === 'llave') { p.keys++; return '¡Llave del jefe! Abre la gran reja'; }
  p.potions += 2; p.coins += 10; g.coinsTotal += 10; return '¡2 pociones y 10 monedas!';
}

// Render Canvas 2D: mundo por capas, entidades ordenadas por profundidad, luz dinámica y ambiente por zona.
import type { Game } from './engine';
import { T, TS } from './maps';
import { bat, bone, flash, golem, hero, item, npc, skeleton, slime, sword } from './sprites';
import { questTarget } from './quests';

type C = CanvasRenderingContext2D;
const glows = new Map<string, HTMLCanvasElement>();
function glow(color: string, r: number) {
  const k = color + r; let cv = glows.get(k); if (cv) return cv;
  cv = document.createElement('canvas'); cv.width = cv.height = r * 2; const c = cv.getContext('2d')!;
  const gr = c.createRadialGradient(r, r, 0, r, r, r); gr.addColorStop(0, color); gr.addColorStop(1, 'rgba(0,0,0,0)');
  c.fillStyle = gr; c.fillRect(0, 0, r * 2, r * 2); glows.set(k, cv); return cv;
}
let vig: HTMLCanvasElement | null = null;
const spr = (c: C, cv: HTMLCanvasElement, x: number, y: number) => c.drawImage(cv, Math.round(x - cv.width / 2), Math.round(y - cv.height + 1));
const shadow = (c: C, x: number, y: number, w: number) => { c.fillStyle = 'rgba(10,6,20,0.32)'; c.beginPath(); c.ellipse(x, y, w, w * 0.4, 0, 0, Math.PI * 2); c.fill(); };

export function drawGame(g: Game) {
  const c = g.ctx, s = g.s, W = g.W, H = g.H, a = g.cur, def = a.def, t = g.t, p = g.p, play = g.mode !== 'attract';
  c.setTransform(1, 0, 0, 1, 0, 0); c.imageSmoothingEnabled = false; c.globalAlpha = 1; c.globalCompositeOperation = 'source-over';
  c.fillStyle = def.id === 'mazmorra' ? '#0b0912' : '#1b4f2e'; c.fillRect(0, 0, W, H);
  const shx = g.shake > 0 ? (Math.random() - 0.5) * g.shake : 0, shy = g.shake > 0 ? (Math.random() - 0.5) * g.shake : 0;
  const ox = Math.round((-g.camX + shx) * s), oy = Math.round((-g.camY + shy) * s);
  c.setTransform(s, 0, 0, s, ox, oy);
  const x0 = Math.max(0, Math.floor(g.camX / TS) - 1), y0 = Math.max(0, Math.floor(g.camY / TS) - 1);
  const x1 = Math.min(def.w - 1, x0 + Math.ceil(W / s / TS) + 2), y1 = Math.min(def.h - 1, y0 + Math.ceil(H / s / TS) + 2);
  const vx = x0 * TS, vy = y0 * TS, vw = (x1 - x0 + 1) * TS, vh = (y1 - y0 + 1) * TS;
  c.drawImage(a.base, vx, vy, vw, vh, vx, vy, vw, vh);

  // tiles animados visibles
  const torches: [number, number][] = [];
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
    const tt = a.tiles[y * def.w + x], px = x * TS, py = y * TS;
    if (tt === T.WATER || tt === T.FOUNT) {
      const ph = (t * 1.6 + x * 0.7 + y * 1.3) % 4; c.fillStyle = 'rgba(220,250,255,0.55)';
      c.fillRect(px + ((ph * 4) | 0), py + 5 + ((x + y) % 3) * 3, 3, 1);
      if (tt === T.FOUNT && a.tiles[y * def.w + x + 1] === T.FOUNT && a.tiles[(y + 1) * def.w + x] === T.FOUNT) {
        c.fillStyle = '#8f88a3'; c.fillRect(px + 12, py + 10, 8, 10); c.fillStyle = '#c9c3d6'; c.fillRect(px + 12, py + 9, 8, 3); c.fillRect(px + 14, py + 4, 4, 6);
        c.fillStyle = '#bff0ff'; c.fillRect(px + 15, py + 1 - (Math.floor(t * 8) % 2), 2, 4);
      }
      if (tt === T.FOUNT && Math.random() < 0.3) g.parts.push({ x: px + 8 + (Math.random() - 0.5) * 6, y: py + 4, vx: (Math.random() - 0.5) * 30, vy: -50, life: 0.5, max: 0.5, color: '#bff0ff', size: 1, g: 160 });
    } else if (tt === T.TORCH) {
      torches.push([px + 8, py + 4]); const f = Math.sin(t * 20 + x) > 0 ? 1 : 0;
      c.fillStyle = '#ff8a2a'; c.fillRect(px + 6, py + 1 - f, 4, 4 + f); c.fillStyle = '#ffd447'; c.fillRect(px + 7, py + 2, 2, 3); c.fillStyle = '#fff'; c.fillRect(px + 7, py + 3, 1, 1);
    }
  }

  // entidades ordenadas por y
  const L: { y: number; f: () => void }[] = [];
  for (const q of a.picks) {
    shadow(c, q.x, q.y, 3);
    L.push({ y: q.y, f: () => { if (q.t > 12 && Math.floor(t * 10) % 2) return; spr(c, item(q.kind, Math.floor(t * 8) % 4), q.x, q.y - q.z - 1 + Math.sin(t * 4 + q.x) * (q.z ? 0 : 1)); } });
  }
  for (const n of def.npcs) {
    const nx = n.x * TS + 8, ny = n.y * TS + 12; shadow(c, nx, ny, 6);
    L.push({ y: ny, f: () => {
      spr(c, npc(n.look, Math.floor(t * 2 + n.x) % 2), nx, ny);
      const ready = n.id === 'anciano' && play && (g.quest === 0 || (g.quest === 1 && g.slimes >= 6) || (g.quest === 2 && p.wings >= 3));
      if (ready) { const by = ny - 28 + Math.sin(t * 6) * 2; c.fillStyle = '#1b1226'; c.fillRect(nx - 2, by - 1, 5, 10); c.fillStyle = '#ffd447'; c.fillRect(nx - 1, by, 3, 6); c.fillRect(nx - 1, by + 7, 3, 2); }
    } });
  }
  for (const e of a.enemies) {
    if (e.dead) continue;
    const big = e.kind === 'jefe'; shadow(c, e.x, e.y + 1, big ? 15 - e.z * 0.2 : e.kind === 'murcielago' ? 4 : 6);
    L.push({ y: e.y, f: () => {
      let cv: HTMLCanvasElement;
      if (e.kind === 'slime' || e.kind === 'slimeRojo') cv = slime(e.kind, e.st === 1 ? (e.z > 3 ? 2 : 1) : Math.sin(e.t * 6) > 0.6 ? 1 : 0);
      else if (e.kind === 'murcielago') cv = bat(Math.floor(e.t * 10) % 2);
      else if (e.kind === 'esqueleto') cv = skeleton(Math.floor(e.t * 6) % 2, e.dir);
      else cv = golem(Math.floor(e.t * 4) % 2, e.hp < e.maxHp * 0.5);
      if (big && e.hp < e.maxHp * 0.5) { c.globalCompositeOperation = 'lighter'; c.drawImage(glow('rgba(255,60,90,0.5)', 30), e.x - 30, e.y - 46 - e.z); c.globalCompositeOperation = 'source-over'; }
      spr(c, e.hit > 0 ? flash(cv) : cv, e.x, e.y + 2 - e.z);
      if (e.hp < e.maxHp && !big) { c.fillStyle = '#1b1226'; c.fillRect(e.x - 7, e.y - 20 - e.z, 14, 3); c.fillStyle = '#ff4d6d'; c.fillRect(e.x - 6, e.y - 19 - e.z, Math.max(0, 12 * e.hp / e.maxHp), 1); }
    } });
  }
  if (play && g.mode === 'play' || (g.mode === 'over' && p.hp > 0)) {
    shadow(c, p.x, p.y + 1, 6);
    L.push({ y: p.y, f: () => {
      if (p.inv > 0 && Math.floor(t * 14) % 2) return;
      const swingOn = p.atk > 0, base = [Math.PI / 2, -Math.PI / 2, Math.PI, 0][p.dir], pr = 1 - Math.max(0, p.atk) / 0.22;
      const ang = base - 1.3 + pr * 2.6;
      const drawSword = () => {
        if (!swingOn) {
          const hx = [6, -6, -3, 3][p.dir], rot = [0.8, -0.8, -0.7, 0.7][p.dir] * Math.PI;
          c.save(); c.translate(p.x + hx, p.y - 4 + (p.moving ? Math.floor(p.walk) % 2 : 0)); c.rotate(rot); c.drawImage(sword(p.sword), -3, -13); c.restore(); return;
        }
        c.save(); c.translate(p.x, p.y - 6);
        c.globalAlpha = 0.55; c.strokeStyle = p.fury > 0 ? '#ffb347' : '#e8fbff'; c.lineWidth = 4; c.beginPath(); c.arc(0, 0, 13, base - 1.3, ang); c.stroke();
        c.globalAlpha = 1; c.rotate(ang + Math.PI / 2); c.drawImage(sword(p.sword), -3, -19); c.restore();
      };
      if (p.dir === 1) drawSword();
      const cv = hero(p.dir, p.moving ? Math.floor(p.walk) % 2 : 0, p.fury > 0);
      if (p.fury > 0) { c.globalCompositeOperation = 'lighter'; c.drawImage(glow('rgba(255,140,40,0.45)', 16), p.x - 16, p.y - 24); c.globalCompositeOperation = 'source-over'; }
      spr(c, cv, p.x, p.y + 2);
      if (p.dir !== 1) drawSword();
    } });
  }
  for (const sh of a.shots) L.push({ y: sh.y, f: () => {
    if (sh.kind === 'orbe') { c.globalCompositeOperation = 'lighter'; c.drawImage(glow('rgba(255,80,220,0.9)', 8), sh.x - 8, sh.y - 8); c.globalCompositeOperation = 'source-over'; c.fillStyle = '#ffe0fa'; c.fillRect(sh.x - 1, sh.y - 1, 3, 3); }
    else { c.save(); c.translate(sh.x, sh.y); c.rotate(sh.t * 14); c.drawImage(bone(), -5, -3); c.restore(); }
  } });
  L.sort((u, v) => u.y - v.y); for (const o of L) o.f();

  for (const q of g.parts) {
    c.globalAlpha = Math.min(1, q.life / q.max * 1.5);
    if (q.glow) { c.globalCompositeOperation = 'lighter'; c.fillStyle = q.color; c.fillRect(q.x - q.size, q.y - q.size, q.size * 2, q.size * 2); c.globalCompositeOperation = 'source-over'; }
    else { c.fillStyle = q.color; c.fillRect(q.x, q.y, q.size, q.size); }
  }
  c.globalAlpha = 1;
  c.drawImage(a.top, vx, Math.max(0, vy - TS), vw, vh + TS, vx, Math.max(0, vy - TS), vw, vh + TS);
  ambient(g, c, torches);

  if (g.mode === 'play' && !g.dialog.length) {
    const tg = questTarget(g);
    if (tg && Math.hypot(tg.x - p.x, tg.y - p.y) > 44) {
      const an = Math.atan2(tg.y - p.y, tg.x - p.x), r = 24 + Math.sin(t * 6) * 2;
      c.save(); c.translate(p.x + Math.cos(an) * r, p.y - 6 + Math.sin(an) * r); c.rotate(an);
      c.fillStyle = '#1b1226'; c.beginPath(); c.moveTo(7, 0); c.lineTo(-5, -6); c.lineTo(-2, 0); c.lineTo(-5, 6); c.closePath(); c.fill();
      c.fillStyle = '#ffd447'; c.beginPath(); c.moveTo(5, 0); c.lineTo(-3, -4); c.lineTo(-1, 0); c.lineTo(-3, 4); c.closePath(); c.fill(); c.restore();
    }
  }
  c.font = 'bold 8px monospace'; c.textAlign = 'center'; c.lineWidth = 2; c.strokeStyle = '#1b1226';
  for (const f of g.texts) { c.globalAlpha = Math.min(1, (0.9 - f.t) * 3); c.strokeText(f.text, f.x, f.y); c.fillStyle = f.color; c.fillText(f.text, f.x, f.y); }
  c.globalAlpha = 1;

  // ---------- espacio de pantalla ----------
  c.setTransform(1, 0, 0, 1, 0, 0);
  if (def.id === 'mazmorra') darkness(g, torches, ox, oy);
  if (!vig || vig.width !== W || vig.height !== H) {
    vig = document.createElement('canvas'); vig.width = W; vig.height = H; const v = vig.getContext('2d')!;
    const gr = v.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.35, W / 2, H / 2, Math.max(W, H) * 0.75);
    gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(1, 'rgba(8,4,20,0.6)'); v.fillStyle = gr; v.fillRect(0, 0, W, H);
  }
  c.drawImage(vig, 0, 0);
  if (g.hurtFlash > 0) { c.fillStyle = `rgba(255,40,70,${g.hurtFlash * 0.6})`; c.fillRect(0, 0, W, H); }
  if (g.fade > 0) { c.fillStyle = `rgba(8,4,16,${Math.min(1, g.fade)})`; c.fillRect(0, 0, W, H); }
}

function ambient(g: Game, c: C, torches: [number, number][]) {
  const t = g.t, id = g.cur.def.id, vw = g.W / g.s, vh = g.H / g.s;
  c.globalCompositeOperation = 'lighter';
  if (id === 'pueblo') {
    c.globalAlpha = 0.9;
    for (let i = 0; i < 6; i++) { // mariposas
      const bx = g.camX + ((i * 97 + t * (8 + i * 3)) % (vw + 40)) - 20, by = g.camY + ((i * 53) % vh) + Math.sin(t * 2 + i) * 12, f = Math.floor(t * 12 + i) % 2;
      c.fillStyle = ['#ffd6f0', '#fff6a0', '#bfe8ff'][i % 3]; c.fillRect(bx - 2, by - f, 2, 2 - f + 1); c.fillRect(bx + 1, by - f, 2, 2 - f + 1);
    }
    c.globalCompositeOperation = 'source-over'; c.globalAlpha = 1;
    for (let i = 0; i < 3; i++) { const cx = g.camX + ((i * 220 + t * 9) % (vw + 260)) - 130, cy = g.camY + (i * 97) % vh; c.drawImage(glow('rgba(10,20,60,0.13)', 70), cx - 70, cy - 40, 140, 80); }
  } else if (id === 'bosque') {
    c.globalAlpha = 0.07; c.fillStyle = '#fff3b0';
    for (let i = 0; i < 4; i++) { const bx = g.camX + ((i * 140 + t * 4) % (vw + 200)) - 100; c.beginPath(); c.moveTo(bx, g.camY); c.lineTo(bx + 30, g.camY); c.lineTo(bx + 30 + vh * 0.6, g.camY + vh); c.lineTo(bx + vh * 0.6, g.camY + vh); c.fill(); }
    c.globalAlpha = 0.9;
    for (let i = 0; i < 26; i++) {
      const fx = ((i * 211.7) % (g.cur.def.w * TS)) + Math.sin(t * 0.7 + i) * 18, fy = ((i * 137.3) % (g.cur.def.h * TS)) + Math.cos(t * 0.5 + i * 2) * 14;
      if (Math.sin(t * 3 + i * 1.7) > -0.2) c.drawImage(glow('rgba(200,255,120,0.9)', 5), fx - 5, fy - 5);
    }
  } else {
    for (const [x, y] of torches) { c.globalAlpha = 0.5 + Math.sin(t * 13 + x) * 0.08; c.drawImage(glow('rgba(255,140,50,0.55)', 26), x - 26, y - 22); }
  }
  c.globalAlpha = 1; c.globalCompositeOperation = 'source-over';
}

function darkness(g: Game, torches: [number, number][], ox: number, oy: number) {
  const lc = g.light.getContext('2d')!, s = g.s, t = g.t;
  lc.globalCompositeOperation = 'source-over'; lc.clearRect(0, 0, g.W, g.H); lc.fillStyle = 'rgba(6,3,18,0.86)'; lc.fillRect(0, 0, g.W, g.H);
  lc.globalCompositeOperation = 'destination-out';
  const hole = (x: number, y: number, r: number) => { const R = r * s; lc.drawImage(glow('rgba(0,0,0,1)', 64), x * s + ox - R, y * s + oy - R, R * 2, R * 2); };
  if (g.mode !== 'attract') hole(g.p.x, g.p.y - 6, 92 + Math.sin(t * 9) * 3);
  else hole(g.camX + g.W / s / 2, g.camY + g.H / s / 2, 140);
  for (const [x, y] of torches) hole(x, y + 6, 62 + Math.sin(t * 11 + x) * 4);
  for (const sh of g.cur.shots) if (sh.kind === 'orbe') hole(sh.x, sh.y, 22);
  for (const e of g.cur.enemies) if (!e.dead && e.kind === 'jefe') hole(e.x, e.y - 14, 46);
  g.ctx.drawImage(g.light, 0, 0);
}

// Sprites en pixel art dibujados con rectángulos y cacheados en canvas con contorno.
import { blob } from './maps';
import type { Dir } from './types';

type C = CanvasRenderingContext2D;
const R = (c: C, x: number, y: number, w: number, h: number, col: string) => { c.fillStyle = col; c.fillRect(x, y, w, h); };
const cache = new Map<string, HTMLCanvasElement>();
const flashes = new WeakMap<HTMLCanvasElement, HTMLCanvasElement>();
const mk = (w: number, h: number) => { const cv = document.createElement('canvas'); cv.width = w; cv.height = h; return cv; };

function bake(key: string, w: number, h: number, draw: (c: C) => void, line = '#1b1226') {
  const hit = cache.get(key); if (hit) return hit;
  const src = mk(w, h); draw(src.getContext('2d')!);
  const sil = mk(w, h), s = sil.getContext('2d')!;
  s.drawImage(src, 0, 0); s.globalCompositeOperation = 'source-in'; s.fillStyle = line; s.fillRect(0, 0, w, h);
  const cv = mk(w + 2, h + 2), c = cv.getContext('2d')!;
  for (const [dx, dy] of [[0, 1], [2, 1], [1, 0], [1, 2]]) c.drawImage(sil, dx, dy);
  c.drawImage(src, 1, 1); cache.set(key, cv); return cv;
}
export function flash(cv: HTMLCanvasElement) {
  let f = flashes.get(cv); if (f) return f;
  f = mk(cv.width, cv.height); const c = f.getContext('2d')!;
  c.drawImage(cv, 0, 0); c.globalCompositeOperation = 'source-in'; c.fillStyle = '#ffffff'; c.fillRect(0, 0, f.width, f.height);
  flashes.set(cv, f); return f;
}
const flip = (c: C, w: number, on: boolean) => { if (on) { c.translate(w, 0); c.scale(-1, 1); } };

export function hero(dir: Dir, fr: number, fury: boolean) {
  return bake(`h${dir}${fr}${fury ? 1 : 0}`, 16, 18, c => {
    flip(c, 16, dir === 2);
    const tun = fury ? '#ff7a2a' : '#2aa198', tunD = fury ? '#c44a12' : '#1b6f6a', skin = '#f4c79a', hair = '#d8642a', boot = '#5a3418';
    const side = dir >= 2, l = fr % 2;
    if (side) { R(c, 5 + (l ? -1 : 1), 14, 3, 3, boot); R(c, 8 + (l ? 1 : -1), 14, 3, 3, boot); }
    else { R(c, 4, 14 - l, 3, 3 + l, boot); R(c, 9, 14 - (1 - l), 3, 3 + (1 - l), boot); }
    R(c, 4, 9, 8, 6, tun); R(c, 4, 13, 8, 1, tunD); R(c, 4, 11, 8, 1, '#6b4423'); R(c, 7, 11, 2, 1, '#ffd447');
    if (!side) { R(c, 2, 9 + l, 2, 4, skin); R(c, 12, 10 - l, 2, 4, skin); R(c, 2, 9 + l, 2, 2, tun); R(c, 12, 10 - l, 2, 2, tun); }
    else { R(c, 7, 10, 3, 3, tunD); R(c, 8, 12, 2, 2, skin); }
    R(c, 4, 8, 8, 2, '#e63946'); if (dir === 1) R(c, 9, 9, 2, 4, '#e63946');
    R(c, 4, 2, 8, 7, skin);
    if (dir === 0) { R(c, 3, 1, 10, 3, hair); R(c, 3, 3, 1, 4, hair); R(c, 12, 3, 1, 4, hair); R(c, 5, 3, 2, 1, hair); R(c, 6, 5, 1, 2, '#1b1226'); R(c, 9, 5, 1, 2, '#1b1226'); R(c, 5, 7, 1, 1, '#ff9a9a'); R(c, 10, 7, 1, 1, '#ff9a9a'); }
    else if (dir === 1) { R(c, 3, 1, 10, 8, hair); R(c, 5, 2, 4, 1, '#f08a4a'); }
    else { R(c, 3, 1, 9, 3, hair); R(c, 3, 3, 4, 5, hair); R(c, 10, 5, 1, 2, '#1b1226'); R(c, 12, 6, 1, 1, skin); R(c, 9, 7, 1, 1, '#ff9a9a'); }
    R(c, 3, 0, 10, 1, '#2d6a4f'); R(c, 4, -1, 7, 2, '#40916c');
  });
}

export function sword(lv: number) {
  return bake(`sw${lv}`, 5, 15, c => {
    const blade = lv >= 3 ? '#9ffcff' : lv === 2 ? '#e8eef8' : '#c8ccd8';
    R(c, 1, 0, 3, 10, blade); R(c, 1, 0, 1, 10, '#ffffff'); R(c, 2, 0, 1, 1, '#ffffff');
    R(c, 0, 10, 5, 1, '#e0a83a'); R(c, 1, 11, 3, 3, '#7a4a26'); R(c, 1, 14, 3, 1, '#ffd447');
  });
}

const SLIME: Record<string, [string, string, string]> = { slime: ['#5fd068', '#2f9a4a', '#c8ffb0'], slimeRojo: ['#ff5a6a', '#b82a44', '#ffc8c8'] };
export function slime(kind: string, fr: number) {
  return bake(`s${kind}${fr}`, 16, 14, c => {
    const [b, d, l] = SLIME[kind] || SLIME.slime, rx = fr === 1 ? 8 : fr === 2 ? 5 : 7, ry = fr === 1 ? 4 : fr === 2 ? 6 : 5;
    blob(c, 8, 13 - ry, rx, ry, d); blob(c, 8, 12 - ry, rx - 1, ry - 1, b); R(c, 8 - rx + 3, 13 - ry * 2 + 2, 3, 2, l); R(c, 9 - rx + 3, 13 - ry * 2 + 4, 1, 1, '#ffffff');
    const ey = 12 - ry; R(c, 5, ey, 2, 3, '#1b1226'); R(c, 10, ey, 2, 3, '#1b1226'); R(c, 5, ey, 1, 1, '#fff'); R(c, 10, ey, 1, 1, '#fff');
    if (kind === 'slimeRojo') { R(c, 4, ey - 2, 3, 1, '#1b1226'); R(c, 10, ey - 2, 3, 1, '#1b1226'); }
  });
}

export function bat(fr: number) {
  return bake(`b${fr}`, 18, 12, c => {
    const w = '#4a2a6a', wl = '#7a4fa8';
    if (fr === 0) { R(c, 1, 1, 6, 2, w); R(c, 0, 0, 3, 2, w); R(c, 3, 3, 4, 2, wl); R(c, 11, 1, 6, 2, w); R(c, 15, 0, 3, 2, w); R(c, 11, 3, 4, 2, wl); }
    else { R(c, 1, 6, 6, 2, w); R(c, 0, 8, 3, 2, w); R(c, 3, 5, 4, 2, wl); R(c, 11, 6, 6, 2, w); R(c, 15, 8, 3, 2, w); R(c, 11, 5, 4, 2, wl); }
    blob(c, 9, 6, 4, 4, '#5b3482'); R(c, 6, 1, 2, 3, '#5b3482'); R(c, 10, 1, 2, 3, '#5b3482');
    R(c, 7, 5, 1, 2, '#ffde4a'); R(c, 10, 5, 1, 2, '#ffde4a'); R(c, 8, 8, 1, 1, '#fff'); R(c, 10, 8, 1, 1, '#fff');
  });
}

export function skeleton(fr: number, dir: Dir) {
  return bake(`k${fr}${dir}`, 14, 18, c => {
    flip(c, 14, dir === 2);
    const b = '#ece6d6', d = '#a8a090', l = fr % 2;
    R(c, 3, 14 - l, 2, 4 + l, b); R(c, 9, 13 + l, 2, 5 - l, b);
    R(c, 4, 9, 6, 5, d); for (let i = 0; i < 3; i++) R(c, 3, 9 + i * 2, 8, 1, b); R(c, 6, 9, 2, 5, b);
    R(c, 1, 9 + l, 2, 5, b); R(c, 11, 10 - l, 2, 5, b);
    blob(c, 7, 4, 5, 4, b); R(c, 4, 7, 6, 2, b); R(c, 4, 4, 2, 2, '#1b1226'); R(c, 8, 4, 2, 2, '#1b1226'); R(c, 5, 5, 1, 1, '#ff3a3a'); R(c, 9, 5, 1, 1, '#ff3a3a');
    R(c, 5, 8, 1, 1, '#1b1226'); R(c, 7, 8, 1, 1, '#1b1226');
  });
}

export function golem(fr: number, rage: boolean) {
  return bake(`g${fr}${rage ? 1 : 0}`, 34, 32, c => {
    const s = '#7d8296', sd = '#565a6e', sl = '#a7adc4', eye = rage ? '#ff3a5a' : '#4af2ff', a = fr % 2 ? 2 : 0;
    R(c, 7, 26, 7, 6, sd); R(c, 20, 26, 7, 6, sd);
    R(c, 0, 10 + a, 7, 14, sd); R(c, 1, 10 + a, 5, 12, s); R(c, 27, 12 - a, 7, 14, sd); R(c, 28, 12 - a, 5, 12, s);
    R(c, 5, 8, 24, 20, sd); R(c, 6, 8, 22, 18, s); R(c, 6, 8, 22, 3, sl); R(c, 9, 14, 4, 1, sd); R(c, 21, 18, 5, 1, sd); R(c, 12, 22, 1, 4, sd);
    R(c, 14, 15, 6, 6, '#2a2440'); R(c, 15, 16, 4, 4, eye); R(c, 16, 16, 1, 1, '#fff');
    R(c, 9, 2, 16, 8, s); R(c, 9, 2, 16, 2, sl); R(c, 11, 5, 4, 2, eye); R(c, 19, 5, 4, 2, eye);
    R(c, 9, 0, 16, 2, '#e0a83a'); R(c, 9, -1, 2, 2, '#ffd447'); R(c, 16, -1, 2, 2, '#ffd447'); R(c, 23, -1, 2, 2, '#ffd447'); R(c, 16, 0, 2, 1, '#e63946');
    R(c, 6, 8, 5, 2, '#4f9a4a'); R(c, 22, 9, 4, 1, '#4f9a4a');
  });
}

export function npc(look: string, fr: number) {
  return bake(`n${look}${fr}`, 16, 20, c => {
    const L: Record<string, [string, string, string]> = { anciano: ['#6b4fa0', '#f2f2f2', '#4a3478'], mercader: ['#b5651d', '#5a3418', '#7a4210'], guardia: ['#8a90a8', '#5a6070', '#e63946'], nina: ['#ff7aa8', '#7a4a26', '#d84a7a'] };
    const [robe, hair, acc] = L[look] || L.anciano, skin = '#f4c79a', b = fr ? 1 : 0;
    R(c, 3, 10, 10, 9, robe); R(c, 3, 17, 10, 2, acc); R(c, 2, 11, 2, 5, robe); R(c, 12, 11, 2, 5, robe); R(c, 2, 15, 2, 2, skin); R(c, 12, 15, 2, 2, skin);
    R(c, 4, 3 + b, 8, 7, skin); R(c, 6, 6 + b, 1, 2, '#1b1226'); R(c, 9, 6 + b, 1, 2, '#1b1226');
    if (look === 'anciano') { R(c, 4, 2 + b, 8, 2, hair); R(c, 4, 8 + b, 8, 5, hair); R(c, 6, 13, 4, 2, hair); R(c, 14, 4, 2, 15, '#8a5530'); R(c, 13, 3, 4, 2, '#4af2ff'); }
    if (look === 'mercader') { R(c, 1, 2 + b, 14, 2, '#2d6a4f'); R(c, 4, 0 + b, 8, 3, '#40916c'); R(c, 5, 12, 6, 7, '#f0e0c0'); R(c, 5, 9 + b, 6, 1, hair); }
    if (look === 'guardia') { R(c, 3, 1 + b, 10, 4, '#c4c8d8'); R(c, 3, 4 + b, 1, 4, '#c4c8d8'); R(c, 12, 4 + b, 1, 4, '#c4c8d8'); R(c, 7, -1 + b, 2, 3, acc); R(c, 14, 0, 1, 19, '#8a5530'); R(c, 13, -2, 3, 3, '#e8eef8'); R(c, 5, 11, 6, 4, '#c4c8d8'); }
    if (look === 'nina') { R(c, 4, 2 + b, 8, 3, hair); R(c, 2, 4 + b, 2, 5, hair); R(c, 12, 4 + b, 2, 5, hair); R(c, 2, 4 + b, 2, 1, acc); R(c, 12, 4 + b, 2, 1, acc); R(c, 7, 8 + b, 2, 1, '#ff9a9a'); }
  });
}

export function item(kind: string, fr: number) {
  return bake(`i${kind}${fr}`, 12, 12, c => {
    if (kind === 'moneda') { const w = [5, 3, 1, 3][fr % 4]; blob(c, 6, 6, w, 5, '#e0a020'); blob(c, 6, 6, Math.max(1, w - 1), 4, '#ffd447'); if (w > 2) R(c, 5, 3, 1, 5, '#fff3b0'); }
    else if (kind === 'gema') { R(c, 4, 1, 4, 2, '#9ffcff'); R(c, 2, 3, 8, 3, '#4ad8ff'); R(c, 3, 6, 6, 2, '#2a8fd8'); R(c, 5, 8, 2, 2, '#1a5fa8'); R(c, 4, 3, 2, 2, '#fff'); }
    else if (kind === 'corazon') { R(c, 1, 2, 4, 5, '#e63946'); R(c, 7, 2, 4, 5, '#e63946'); R(c, 2, 7, 8, 2, '#e63946'); R(c, 4, 9, 4, 2, '#c42a3a'); R(c, 5, 4, 2, 3, '#e63946'); R(c, 2, 3, 2, 2, '#ffb3b3'); }
    else if (kind === 'pocion') { R(c, 5, 0, 2, 2, '#c49a6c'); R(c, 4, 2, 4, 2, '#d8e8f0'); blob(c, 6, 7, 4, 4, '#ff3a6a'); R(c, 4, 5, 2, 2, '#ffd0e0'); }
    else if (kind === 'ala') { R(c, 2, 2, 8, 3, '#7a4fa8'); R(c, 1, 5, 6, 3, '#5b3482'); R(c, 0, 8, 3, 2, '#4a2a6a'); R(c, 3, 2, 6, 1, '#b48ae0'); }
    else if (kind === 'furia') { blob(c, 6, 6, 5, 5, '#ff7a2a'); blob(c, 6, 6, 3, 3, '#ffd447'); R(c, 5, 4, 2, 2, '#ffffff'); }
    else if (kind === 'llave') { blob(c, 3, 5, 3, 3, '#ffd447'); R(c, 2, 4, 2, 2, '#7a4a10'); R(c, 6, 5, 6, 2, '#ffd447'); R(c, 9, 7, 1, 2, '#ffd447'); R(c, 11, 7, 1, 3, '#ffd447'); }
    else if (kind === 'botas') { R(c, 2, 1, 4, 7, '#3a7ad8'); R(c, 2, 8, 8, 3, '#2a5aa8'); R(c, 2, 1, 4, 1, '#ffd447'); R(c, 7, 2, 3, 1, '#9ffcff'); R(c, 8, 4, 3, 1, '#9ffcff'); }
  });
}

export function bone() { return bake('bone', 8, 4, c => { R(c, 2, 1, 4, 2, '#ece6d6'); R(c, 0, 0, 2, 4, '#ece6d6'); R(c, 6, 0, 2, 4, '#ece6d6'); }); }

export function spriteURL(cv: HTMLCanvasElement, scale = 4) {
  const o = mk(cv.width * scale, cv.height * scale), c = o.getContext('2d')!;
  c.imageSmoothingEnabled = false; c.drawImage(cv, 0, 0, o.width, o.height); return o.toDataURL();
}

